arranque:		; El arranque (en la pagina 1): la RAM de 0xE000 a cero (0x1100 bytes), la pila, la interrupcion en H.TIMI (0xB475), SCREEN 2 en negro, la fuente de la BIOS en los tres tercios, los colores, los sprites, el registro 1 y el record a 30.000
	ld hl,0e000h		;7e80   ; 0xE000-0xF0FF...
	ld bc,01100h		;7e83   ; ...0x1100 bytes...
init_borra:		; ...a cero
	ld (hl),000h		;7e86   ; un byte a 0
	inc hl			;7e88   ; el siguiente
	dec c			;7e89   ; 256 bytes...
	jr nz,init_borra		;7e8a   ; los 256
	djnz init_borra		;7e8c   ; ...17 veces
	ld sp,0f200h		;7e8e   ; la pila
	ld hl,0b475h		;7e91   ; la interrupcion: 0xB475...
	ld (0fda0h),hl		;7e94   ; ...en H.TIMI...
	ld a,0c3h		;7e97   ; ...con su "jp"
	ld (0fd9fh),a		;7e99   ; ...0xFD9F
	call 0007eh		;7e9c   ; SETGRP: SCREEN 2
	xor a			;7e9f   ; fondo y borde negros...
	ld (0f3eah),a		;7ea0   ; BAKCLR = 0
	ld (0f3ebh),a		;7ea3   ; BDRCLR = 0
	dec a			;7ea6   ; ...letras blancas (0xFF)
	ld (0f3e9h),a		;7ea7   ; FORCLR = 0xFF
	call 00062h		;7eaa   ; CHGCLR
	ld de,00000h		;7ead   ; la fuente de la BIOS (0x1D3F) en la tabla de dibujos...
	ld b,003h		;7eb0   ; tres tercios
init_letras:
	call letras_pon		;7eb2   ; las letras
	djnz init_letras		;7eb5
	xor a			;7eb7   ; el dibujo de la casilla 0x10 (el espacio)...
	ld hl,00080h		;7eb8   ; ...a cero (0x0080), en los tres tercios
	ld b,003h		;7ebb   ; tres tercios
L_7EBD:
	call colores_ocho		;7ebd
	djnz L_7EBD		;7ec0
	ld hl,02000h		;7ec2   ; la tabla de colores entera...
	ld bc,01800h		;7ec5   ; ...0x1800 bytes...
	ld a,0f0h		;7ec8   ; ...blanco sobre negro
	call 00056h		;7eca   ; FILVRM
	call sprites_dibujos		;7ecd   ; los dibujos de los sprites
	ld a,0a2h		;7ed0   ; el registro 1 a 0xA2: sprites de 16 x 16
	ld b,a			;7ed2
	ld c,001h		;7ed3
	call 00047h		;7ed5   ; WRTVDP
	ld a,003h		;7ed8   ; el record: 0xE090 = 3...
	ld (0e090h),a		;7eda
	ld a,030h		;7edd   ; ...0xE095 = 0x30: 030000
	ld (0e095h),a		;7edf
	ei			;7ee2   ; con interrupciones
titulo:		; El titulo: el sonido a cero, la pantalla, las casillas del nombre (0x200), sus colores, la presentacion de CASIO; las teclas 8, 9, -, ^ y la del yen pulsadas a la vez (la fila 1 = 0xE0) sin el 0 (0xE023 = 1); el nombre (0x5695, 4 filas de 16), CASIO, PUSH TRIG:1 OR SPACE y el copyright; con el boton, la partida; a los 0xF0 cuadros, la demostracion
	call sonido_reinicia		;7ee3   ; el sonido a cero
	call pantalla_limpia		;7ee6   ; la pantalla limpia
	ld de,00200h		;7ee9   ; los dibujos del nombre (casilla 0x40)...
	ld b,003h		;7eec   ; ...en los tres tercios
	call titulo_casillas		;7eee
	ld hl,02200h		;7ef1   ; sus colores
	ld b,003h		;7ef4
L_7EF6:
	call colores_titulo		;7ef6
	djnz L_7EF6		;7ef9
	call 00044h		;7efb   ; ENASCR
	call presentacion		;7efe   ; la presentacion de CASIO
	ld a,001h		;7f01   ; la fila 1...
	call 00141h		;7f03   ; SNSMAT
	cp 0e0h		;7f06   ; ...con 8, 9, -, ^ y el yen pulsadas (0xE0)?
	jr nz,titulo_textos		;7f08   ; no
	xor a			;7f0a   ; la fila 0...
	call 00141h		;7f0b   ; SNSMAT
	bit 0,a		;7f0e   ; ...el 0 pulsado?
	jr z,titulo_textos		;7f10   ; si: nada
	ld a,001h		;7f12   ; 0xE023 = 1
	ld (0e023h),a		;7f14
titulo_textos:		; El nombre (0x5695: 4 filas de 16 casillas) desde la fila 8, columna 8; CASIO (0x56D5) en la fila 16; PUSH TRIG:1 OR SPACE (0x56DB) en la 18 y el copyright (0x56EF) en la 20
	ld hl,05695h		;7f17   ; el nombre
	ld de,01908h		;7f1a   ; en la fila 8, columna 8
	ld b,004h		;7f1d   ; cuatro filas
L_7F1F:
	call fila_16		;7f1f
	djnz L_7F1F		;7f22
	ld hl,056d5h		;7f24   ; CASIO (casillas 0x8A-0x8F)
	ld de,01a0dh		;7f27   ; en la fila 16, columna 13
	ld bc,00006h		;7f2a
	call 0005ch		;7f2d   ; LDIRVM
	ld hl,056dbh		;7f30   ; PUSH TRIG:1 OR SPACE
	ld de,01a46h		;7f33   ; en la fila 18, columna 6
	ld bc,00014h		;7f36
	call 0005ch		;7f39   ; LDIRVM
	ld hl,056efh		;7f3c   ; COPYRIGHT 1986 (c) CASIO
	ld de,01a85h		;7f3f   ; en la fila 20, columna 5
	ld bc,00016h		;7f42
	call 0005ch		;7f45   ; LDIRVM
	call 00044h		;7f48   ; ENASCR
	xor a			;7f4b   ; la cuenta a 0
	ld (0e018h),a		;7f4c
titulo_espera:		; Hasta 0xF0 cuadros, el boton
	ld a,(0e018h)		;7f4f   ; 0xF0 cuadros?
	cp 0f0h		;7f52
	jp nc,demostracion		;7f54   ; si: la demostracion
	ld a,(0e026h)		;7f57   ; el boton?
	and a			;7f5a
	jr z,titulo_espera		;7f5b
	xor a			;7f5d   ; pulsado: atendido...
	ld (0e026h),a		;7f5e   ; el boton de empezar
	jr partida_nueva		;7f61   ; ...y la partida
demostracion:		; La demostracion: al azar, la casa (0xE00A = 0) con 0xE0A1 = 2 o 4
	ld a,r		;7f63   ; al azar...
	and 003h		;7f65
	cp 002h		;7f67   ; ...0 o 1...
	jr c,demostracion_b		;7f69
	xor a			;7f6b   ; ...2 o 3: 0xE0A1 = 2
	ld (0e00ah),a		;7f6c   ; la sala
	inc a			;7f6f
	ld (0e0a2h),a		;7f70
	ld a,002h		;7f73
	ld (0e0a1h),a		;7f75
	jr demostracion_va		;7f78
demostracion_b:		; 0xE0A1 = 4
	ld a,000h		;7f7a
	ld (0e00ah),a		;7f7c   ; la sala
	ld a,004h		;7f7f
	ld (0e0a1h),a		;7f81
	ld a,001h		;7f84
	ld (0e0a2h),a		;7f86
demostracion_va:		; La demostracion (0xE028 = 1), sus mandos desde 0x0000 (0xE029: la BIOS) y tres vidas
	xor a			;7f89   ; todo a cero
	ld (0e098h),a		;7f8a
	ld (0e023h),a		;7f8d
	ld (0e0a9h),a		;7f90   ; el aguante (0xE0A9, en medias)
	inc a			;7f93   ; la demostracion: 0xE028 = 1
	ld (0e028h),a		;7f94
	ld hl,00000h		;7f97   ; sus mandos, desde 0x0000
	ld (0e029h),hl		;7f9a
	ld (0e0a8h),a		;7f9d   ; tres (0xE0A8 = 1, sic)
	jp sala_empieza		;7fa0   ; a jugarla
partida_nueva:		; La partida: los puntos a cero, jugando (0xE000 = 1), las vidas a 3 (0xE0A8); con las teclas del titulo, el aguante lleno (0xE0A9 = 6); 0xE02B-0xE082 a cero
	ld hl,0e001h		;7fa3   ; los puntos (0xE001-0xE006) a cero
	ld b,006h		;7fa6   ; seis cifras
partida_borra:
	ld (hl),000h		;7fa8   ; una cifra a 0
	inc hl			;7faa   ; la siguiente
	djnz partida_borra		;7fab   ; seis
	xor a			;7fad   ; y los tres bytes BCD
	ld (0e00eh),a		;7fae   ; los puntos a cero
	ld (0e00dh),a		;7fb1   ; los puntos a cero
	ld (0e00ch),a		;7fb4
partida_va:		; Todo a cero y a jugar
