	ld (0e047h),a		;84cc   ; 0xE047 (el final)
	xor a			;84cf
	ld (0e1b0h),a		;84d0   ; 0xE1B0 (el suceso)
	ld (0e1b2h),a		;84d3   ; los golpes al suceso (0xE1B2)
	ld (0e1b8h),a		;84d6
	ld a,007h		;84d9   ; la musica 7
	call musica_pide		;84db   ; la musica
	ret			;84de
dibujo_suceso:		; Los dibujos (0x2C0 bytes de HL) a las casillas 0x90 de los tres tercios y sus colores (HL + 0x1000)
	ld de,00480h		;84df   ; a la casilla 0x90
	call tercios_2c0		;84e2
	ld de,01000h		;84e5   ; los colores: + 0x1000
	add hl,de			;84e8
	ld de,02480h		;84e9   ; a sus colores
tercios_2c0:		; 0x2C0 bytes en los tres tercios
	ld b,003h		;84ec
L_84EE:
	push bc			;84ee   ; en este tercio
	push hl			;84ef
	ld bc,002c0h		;84f0   ; 0x2C0 bytes
	call 0005ch		;84f3   ; LDIRVM
	ld bc,00800h		;84f6   ; el siguiente tercio
	add hl,bc			;84f9
	ex de,hl			;84fa
	pop hl			;84fb
	pop bc			;84fc
	djnz L_84EE		;84fd   ; tres
	ret			;84ff
borra_11:		; 11 filas de 11 casillas de 0x554F (en blanco) desde DE; 0xE1B0 = 0
	ld b,00bh		;8500   ; 11 filas
L_8502:
	push bc			;8502   ; una fila
	ld bc,0000bh		;8503   ; 11 casillas
	ld hl,0554fh		;8506   ; en blanco
	call 0005ch		;8509   ; LDIRVM
	ld de,00020h		;850c   ; la fila siguiente
	add hl,de			;850f   ; la fila siguiente
	ex de,hl			;8510
	pop bc			;8511
	djnz L_8502		;8512   ; 11 filas
	xor a			;8514   ; a cero
	ld (0e1b0h),a		;8515   ; 0xE1B0 (el suceso)
	ret			;8518
dibujo_8x8:		; 8 filas de 8 casillas de HL a la VRAM DE
	ld c,008h		;8519   ; 8 filas
L_851B:
	push bc			;851b
	ld bc,00008h		;851c   ; 8 casillas
	call 0005ch		;851f   ; LDIRVM
	pop bc			;8522
	push de			;8523
	ld de,00020h		;8524   ; la fila siguiente
	add hl,de			;8527
	pop de			;8528
	ex de,hl			;8529
	dec c			;852a
	jr nz,L_851B		;852b
	ret			;852d

; ----------------------------------------------------------------------
; DATOS suceso_tabla: Por sala (0-4), el valor de 0xE0A3 con que sale su
;   suceso
;   0x852e..0x8533  (5 bytes)
DATA_suceso_tabla:
	defb 009h,012h,01eh,02fh,044h	; 852e

; ----------------------------------------------------------------------
; DATOS suceso_dibujos: Por sala (0-4), el dibujo de su suceso (0x6800,
;   0x6C00, 0x6A80, 0x6B80...)
;   0x8533..0x853d  (10 bytes)
DATA_suceso_dibujos:
	defb 000h,068h,000h,06ch,000h,06ah,080h,06bh,080h,06bh	; 8533  .h.l.j.k.k

; ======================================================================
; CODIGO 0x853d..0x8f91  (2644 bytes)
; ======================================================================


borde_parpadea:		; El borde blanco y negro cada 4 cuadros, 0x40 cuadros
	xor a			;853d   ; a cero
	ld (0e1a0h),a		;853e
	ld (0e012h),a		;8541   ; la cuenta de cuadros
	ld (0e013h),a		;8544
borde_cuadro:		; Un cuadro
	ld a,(0e012h)		;8547   ; un cuadro?
	cp 001h		;854a
	jr c,borde_cuadro		;854c
	xor a			;854e   ; a cero
	ld (0e012h),a		;854f   ; la cuenta de cuadros
	ld a,(0e013h)		;8552   ; 0x41 cuadros?
	cp 041h		;8555
	ret nc			;8557   ; si: fuera
	and 004h		;8558   ; cada 4: negro o blanco
	and a			;855a
	jr nz,borde_blanco		;855b
borde_pon:		; BDRCLR = A y CHGCLR
	ld (0f3ebh),a		;855d   ; el borde
	call 00062h		;8560   ; CHGCLR
	jr borde_cuadro		;8563
borde_blanco:		; Blanco
	ld a,00fh		;8565
	jr borde_pon		;8567
dibujo_deshace:		; El borde parpadea y el dibujo de las casillas 0x90-0xE7 se deshace: cinco pasadas en las que cada byte de dibujo se queda con bits al azar (R) y se copia a los tres tercios
	call borde_parpadea		;8569   ; el borde
	ld a,005h		;856c   ; cinco pasadas
	ld (0e1a6h),a		;856e
dibujo_deshace_pasada:		; Una pasada: los 0x2C0 bytes de 0x0480 (las casillas 0x90-0xE7)
	ld hl,02480h		;8571   ; el primer tercio...
	ld (0e1a0h),hl		;8574
	ld hl,02c80h		;8577   ; ...el segundo...
	ld (0e1a2h),hl		;857a
	ld hl,03480h		;857d   ; ...el tercero
	ld (0e1a4h),hl		;8580
	ld bc,002c0h		;8583   ; 0x2C0 bytes
dibujo_deshace_byte:		; Un byte: RDVRM, AND con R, a los tres tercios
	ld hl,(0e1a0h)		;8586   ; el byte...
	call 0004ah		;8589   ; RDVRM
	push bc			;858c
	ld b,a			;858d
	ld a,r		;858e   ; al azar...
	and b			;8590   ; ...algunos bits fuera
	call 0004dh		;8591   ; WRTVRM
	inc hl			;8594
	ld (0e1a0h),hl		;8595
	ld hl,(0e1a2h)		;8598   ; el segundo tercio
	call 0004dh		;859b   ; WRTVRM
	inc hl			;859e
	ld (0e1a2h),hl		;859f
	ld hl,(0e1a4h)		;85a2   ; el tercero
	call 0004dh		;85a5   ; WRTVRM
	inc hl			;85a8
	ld (0e1a4h),hl		;85a9
	inc de			;85ac
	pop bc			;85ad
	dec bc			;85ae   ; uno menos
	ld a,c			;85af
	or b			;85b0
	jr nz,dibujo_deshace_byte		;85b1
	ld a,(0e1a6h)		;85b3   ; una pasada menos
	dec a			;85b6
	ld (0e1a6h),a		;85b7
	jr nz,dibujo_deshace_pasada		;85ba
	ret			;85bc
ataque:		; El ataque (boton 1): el arma (0xE320) sale del protagonista hacia su lado (+0x17), 4 pixeles por cuadro; con el aguante lleno (0xE0A9 / 2 = las vidas), el ataque largo (+0x0D = 2); si no, el corto (1, 5 cuadros)
	ld a,(ix+00dh)		;85bd   ; atacando?
	and a			;85c0
	jr nz,ataque_vuela		;85c1   ; si: sigue
	ld a,(0e022h)		;85c3   ; el boton 1?
	and a			;85c6
	ret z			;85c7
	xor a			;85c8   ; atendido
	ld (0e022h),a		;85c9   ; el boton 1
	ld a,(ix+004h)		;85cc   ; tocado?
	and a			;85cf
	ret nz			;85d0
	ld a,(ix+006h)		;85d1   ; saltando?
	and a			;85d4
	ret nz			;85d5
	ld a,(0e0a9h)		;85d6   ; 0xE0A9 / 2...
	srl a		;85d9
	ld b,a			;85db
	ld a,(0e0a8h)		;85dc   ; ...contra las vidas
	cp b			;85df
	jr z,ataque_largo		;85e0
	ld (ix+00dh),001h		;85e2   ; el corto: 1
	jr ataque_sale		;85e6
ataque_largo:		; El largo: 2
	ld (ix+00dh),002h		;85e8   ; atacando (+0x0D)
ataque_sale:		; El sonido 3 y el arma donde el protagonista, color 11, hacia su lado (dibujo 0x28 o 0x2C)
	ld a,003h		;85ec   ; el sonido 3
	call sonido_a_pide		;85ee   ; el sonido del canal A
	ld a,(ix+000h)		;85f1   ; la Y...
	ld (ix+020h),a		;85f4   ; la Y del arma
	ld a,(ix+001h)		;85f7   ; ...y la X del protagonista
	ld (ix+021h),a		;85fa   ; la X del arma
	ld (ix+023h),00bh		;85fd   ; color 11
	ld a,(ix+017h)		;8601   ; su lado?
	and a			;8604
	jr nz,ataque_izq		;8605
	ld (ix+018h),000h		;8607   ; a la derecha: dibujo 0x28
	ld (ix+022h),028h		;860b   ; el dibujo del arma
	jr ataque_vuela		;860f
ataque_izq:		; A la izquierda: dibujo 0x2C
	ld (ix+018h),001h		;8611
	ld (ix+022h),02ch		;8615   ; el dibujo del arma
ataque_vuela:		; 4 pixeles por cuadro hacia su lado; el corto, 5 cuadros; color 15 o 10 cada 4
	xor a			;8619   ; el boton, atendido
	ld (0e022h),a		;861a   ; el boton 1
	ld a,(ix+018h)		;861d   ; el lado
	and a			;8620
	jr nz,ataque_vuela_izq		;8621
	ld a,(ix+021h)		;8623   ; fuera por la derecha?
	cp 0ech		;8626
	jr nc,ataque_fin		;8628
	inc (ix+021h)		;862a   ; 4 a la derecha
	inc (ix+021h)		;862d   ; la X del arma, uno mas
	inc (ix+021h)		;8630   ; la X del arma, uno mas
	inc (ix+021h)		;8633   ; la X del arma, uno mas
	jr ataque_corto		;8636
ataque_vuela_izq:		; 4 a la izquierda
	ld a,(ix+021h)		;8638   ; fuera por la izquierda?
	cp 004h		;863b
	jr c,ataque_fin		;863d
	dec (ix+021h)		;863f   ; la X del arma, uno menos
	dec (ix+021h)		;8642   ; la X del arma, uno menos
	dec (ix+021h)		;8645   ; la X del arma, uno menos
	dec (ix+021h)		;8648   ; la X del arma, uno menos
ataque_corto:		; El corto: 5 cuadros
	ld a,(ix+00dh)		;864b   ; el corto?
	cp 001h		;864e
	jr nz,ataque_color		;8650
	inc (ix+019h)		;8652   ; un cuadro mas
	ld a,(ix+019h)		;8655
	cp 005h		;8658   ; 5?
	jr c,ataque_color		;865a
	jr ataque_fin		;865c
ataque_color:		; Color 15 o 10, cada 4 cuadros
	ld a,(0e012h)		;865e   ; la cuenta de cuadros
	and 004h		;8661
	and a			;8663
	jr nz,ataque_color_10		;8664
	ld (ix+023h),00fh		;8666   ; el color del arma
	ret			;866a
ataque_color_10:		; 10
	ld (ix+023h),00ah		;866b   ; el color del arma
	ret			;866f
ataque_fin:		; El arma fuera y el ataque a 0
	ld (ix+020h),0f0h		;8670   ; la Y del arma
	ld (ix+00dh),000h		;8674   ; atacando (+0x0D)
	ld (ix+019h),000h		;8678
	ret			;867c
tocado:		; Tocado (+0x1F): cada 256 cuadros una vez mas (+0x1E); desde la cuarta, parpadea; a la quinta, se acaba
	ld a,(ix+01fh)		;867d   ; tocado?
	and a			;8680
	jp z,parpadeo_corto		;8681   ; no: el otro parpadeo
	inc (ix+01fh)		;8684   ; un cuadro mas
	jr nz,tocado_parpadea		;8687
	inc (ix+01fh)		;8689
	inc (ix+01eh)		;868c   ; una vez mas
	ld a,(ix+01eh)		;868f
	cp 005h		;8692   ; la quinta?
	jr z,tocado_fin		;8694
tocado_parpadea:		; Desde la cuarta, color 0 o 13 cada 4 cuadros
	ld a,(ix+01eh)		;8696
	cp 004h		;8699
	jr c,tocado_negro		;869b
	ld a,(0e012h)		;869d   ; la cuenta de cuadros
	and 004h		;86a0
	and a			;86a2
	jr nz,tocado_13		;86a3
tocado_negro:		; Color 0
	ld (ix+003h),000h		;86a5   ; su color
	jr parpadeo_corto		;86a9
tocado_13:		; Color 13
	ld (ix+003h),00dh		;86ab   ; su color
	jr parpadeo_corto		;86af
tocado_fin:		; Color 13 y se acaba
	ld (ix+003h),00dh		;86b1   ; color 13 y a cero
	ld (ix+01eh),000h		;86b5
	ld (ix+01fh),000h		;86b9
parpadeo_corto:		; El otro parpadeo (+0x1A): 0x20 cuadros alternando 7 y 15 cada 2; luego 13
	ld a,(ix+01ah)		;86bd   ; hay?
	and a			;86c0
	ret z			;86c1
	inc (ix+01ah)		;86c2   ; un cuadro mas
	ld a,(ix+01ah)		;86c5
	cp 020h		;86c8   ; 0x20?
	jr c,parpadeo_corto_pon		;86ca
	ld (ix+01ah),000h		;86cc   ; se acabo...
	ld (ix+003h),00dh		;86d0   ; ...color 13
	ret			;86d4
parpadeo_corto_pon:		; Color 7 o 15
	ld a,(0e012h)		;86d5   ; cada 2 cuadros, 7 o 15
	and 002h		;86d8
	and a			;86da
	jr nz,parpadeo_corto_15		;86db
	ld (ix+003h),007h		;86dd   ; su color
	ret			;86e1
parpadeo_corto_15:		; 15
	ld (ix+003h),00fh		;86e2   ; su color
	ret			;86e6
caida:		; La caida: sin nada debajo (las casillas de los pies, 0x34-0x3B o 0x80 o mas, sujetan), cae (+9) con el sonido 6; cayendo, 3 pixeles por cuadro hasta tocar suelo en una fila exacta
	ld a,(ix+005h)		;86e7   ; +5?
	and a			;86ea
	ret nz			;86eb
	ld a,(ix+009h)		;86ec   ; cayendo?
	and a			;86ef
	jr nz,caida_va		;86f0
	ld a,(ix+006h)		;86f2   ; tocado?
	and a			;86f5
	ret nz			;86f6
caida_mira:		; Las casillas de los pies
	call casillas_pies		;86f7   ; las de los pies
	ld a,(ix+014h)		;86fa   ; la primera...
	cp 034h		;86fd   ; ...por debajo de 0x34: no sujeta
	jr c,caida_no		;86ff
	cp 03ch		;8701   ; ...0x34-0x3B: sujeta?
	jr c,L_8709		;8703
	cp 080h		;8705   ; ...0x80 o mas?
	jr c,caida_no		;8707
L_8709:
	ld a,(ix+015h)		;8709   ; la segunda
	cp 034h		;870c
	jr c,caida_no		;870e
	cp 03ch		;8710
	jr c,caida_empieza		;8712
	cp 080h		;8714
	jr c,caida_no		;8716
caida_empieza:		; No sujetan: cae (+9 = 1) con el sonido 6
	ld (ix+009h),001h		;8718   ; cayendo (+9)
	ld a,006h		;871c
	call sonido_a_pide		;871e   ; el sonido del canal A
	jr caida_va		;8721
caida_no:		; Sujeta: nada
	ld (ix+00ch),000h		;8723
	ret			;8727
caida_va:		; Cayendo: los empujes (+0x0C) y 3 pasos de 1 pixel
	ld a,(ix+00ch)		;8728
	cp 001h		;872b
	jr nz,L_8734		;872d
	call empuje_der		;872f
	jr caida_pasos		;8732
L_8734:
	cp 002h		;8734
	jr nz,caida_pasos		;8736
	call empuje_izq		;8738
caida_pasos:		; Tres pixeles
	ld b,003h		;873b
caida_paso:		; Un pixel: si las de los pies no sujetan, 1 abajo (y por debajo de 0x9F, a la sala de abajo)
	push bc			;873d   ; las de los pies
	call casillas_pies		;873e
	ld a,(ix+014h)		;8741   ; la casilla de un pie
	cp 034h		;8744
	jr c,caida_suelo		;8746
	cp 03ch		;8748
	jr c,caida_mira2		;874a
	cp 080h		;874c
	jr c,caida_suelo		;874e
caida_mira2:		; La segunda
	ld a,(ix+015h)		;8750   ; la del otro
	cp 034h		;8753
	jr c,caida_suelo		;8755
	cp 03ch		;8757
	jr c,caida_baja		;8759
	cp 080h		;875b
	jr c,caida_suelo		;875d
caida_baja:		; 1 abajo; pasada la Y 0x9F, a la sala de abajo
	inc (ix+000h)		;875f   ; 1 abajo...
	inc (ix+010h)		;8762   ; ...los dos sprites
	ld a,(ix+000h)		;8765   ; la Y...
	cp 09fh		;8768   ; ...0x9F?
	jr c,caida_paso_sig		;876a
	call pantalla_abajo		;876c
	and a			;876f
	jr z,caida_paso_sig		;8770
	call pantalla_cambia		;8772
caida_paso_sig:		; El siguiente
	pop bc			;8775
	djnz caida_paso		;8776
	ret			;8778
caida_suelo:		; Las del suelo (casillas_suelo): si sujetan y esta en fila exacta, se para; el dibujo de pie
	call casillas_suelo		;8779   ; las del suelo
	ld a,(ix+014h)		;877c   ; la casilla de un pie
	cp 03ch		;877f
	jr c,caida_suelo2		;8781
	cp 080h		;8783
	jr c,caida_baja		;8785
caida_suelo2:		; La segunda
	ld a,(ix+015h)		;8787   ; la del otro
	cp 03ch		;878a
	jr c,caida_para		;878c
	cp 080h		;878e
	jr c,caida_baja		;8790
caida_para:		; En fila exacta: se para
	ld a,(ix+000h)		;8792   ; fila exacta?
	and 007h		;8795
	and a			;8797
	jr nz,caida_baja		;8798
	pop bc			;879a
	ld (ix+009h),000h		;879b   ; parado
	ld (ix+00ch),000h		;879f
	ld a,(ix+007h)		;87a3   ; de pie: su dibujo...
	ld (ix+002h),a		;87a6   ; su dibujo
	add a,060h		;87a9   ; ...y +0x60 el de abajo
	ld (ix+012h),a		;87ab   ; el dibujo de su segundo sprite
	ret			;87ae
prota_mueve:		; La palanca (0xE180): 1 arriba, 2-4 derecha, 5 abajo, 6-8 izquierda; nada con la sala acabada, con 0xE047 = 2, tocado o cayendo
	ld a,(0e186h)		;87af   ; la sala acabada?
	and a			;87b2
	ret nz			;87b3
	ld a,(0e047h)		;87b4   ; 0xE047 = 2?
	cp 002h		;87b7
	ret z			;87b9
	ld a,(ix+005h)		;87ba   ; tocado?
	and a			;87bd
	ret nz			;87be
	ld a,(ix+009h)		;87bf   ; cayendo?
	and a			;87c2
	ret nz			;87c3
	ld a,(0e180h)		;87c4   ; la palanca
	and a			;87c7
	jr z,prota_quieto		;87c8
	cp 001h		;87ca   ; 1: arriba
	jr z,L_8822		;87cc
	cp 002h		;87ce   ; 2-4: derecha
	jp z,L_8873		;87d0
	cp 003h		;87d3
	jp z,L_8873		;87d5
	cp 004h		;87d8
	jp z,L_8873		;87da
	cp 005h		;87dd   ; 5: abajo
	jp z,L_884A		;87df
	cp 006h		;87e2   ; 6-8: izquierda
	jp z,L_88AB		;87e4
	cp 007h		;87e7
	jp z,L_88AB		;87e9
	cp 008h		;87ec
	jp z,L_88AB		;87ee
prota_quieto:		; Quieto: de pie
	ld a,(ix+004h)		;87f1   ; tocado (+4)
	and a			;87f4
	jr z,L_8806		;87f5
	ld a,(ix+007h)		;87f7   ; su dibujo de pie (+7)
	ld (ix+002h),a		;87fa   ; su dibujo
	add a,060h		;87fd
	ld (ix+012h),a		;87ff   ; el dibujo de su segundo sprite
	ld (ix+004h),000h		;8802   ; tocado (+4)
L_8806:
	ld a,(ix+002h)		;8806   ; su dibujo
	cp 010h		;8809
	jr nz,L_8816		;880b
	ld (ix+002h),00ch		;880d   ; su dibujo
	ld (ix+012h),06ch		;8811   ; el dibujo de su segundo sprite
	ret			;8815
L_8816:
	cp 018h		;8816
	ret nz			;8818
	ld (ix+002h),014h		;8819   ; su dibujo
	ld (ix+012h),074h		;881d   ; el dibujo de su segundo sprite
	ret			;8821
