	ld (ix+012h),0bch		;ae5e   ; el dibujo de su segundo sprite
L_AE62:
	ld a,(0e014h)		;ae62   ; la cuenta de cuadros
	and 008h		;ae65
	add a,007h		;ae67
	ld (ix+003h),a		;ae69   ; su color
	ld a,(0e012h)		;ae6c   ; la cuenta de cuadros
	cp 040h		;ae6f
	jr c,L_AE34		;ae71
	call sonido_reinicia		;ae73
L_AE76:
	ld a,(0e012h)		;ae76   ; la cuenta de cuadros
	cp 043h		;ae79
	jr c,L_AE76		;ae7b
	ld a,(0e183h)		;ae7d
	cp 001h		;ae80
	jr nz,L_AE8E		;ae82
	ld a,(0e0a8h)		;ae84   ; las vidas (0xE0A8)
	and a			;ae87
	jp z,L_AF20		;ae88
	jp L_AEE1		;ae8b
L_AE8E:
	call objetos_fuera		;ae8e
	call pantalla_cierra		;ae91
	ld de,018c7h		;ae94
	ld hl,0af4dh		;ae97
	ld bc,00013h		;ae9a
	call 0005ch		;ae9d   ; LDIRVM
	ld de,01907h		;aea0
	ld hl,0af60h		;aea3
	ld bc,00013h		;aea6
	call 0005ch		;aea9   ; LDIRVM
	xor a			;aeac   ; las cuentas y los botones a 0
	ld (0e010h),a		;aead   ; las cuentas...
	ld (0e1a0h),a		;aeb0   ; 0xE1A0
	ld (0e020h),a		;aeb3   ; ...y los botones a 0
	ld (0e022h),a		;aeb6   ; el boton 1
	ld a,006h		;aeb9
	call musica_pide		;aebb   ; la musica
L_AEBE:
	ld a,(0e022h)		;aebe   ; el boton 1
	and a			;aec1
	jr z,L_AEC6		;aec2
	jr L_AECE		;aec4
L_AEC6:
	ld a,(0e020h)		;aec6   ; el boton 2
	and a			;aec9
	jr z,L_AEBE		;aeca
	jr L_AF20		;aecc
L_AECE:
	ld a,(0e0a8h)		;aece   ; las vidas (0xE0A8)
	cp 001h		;aed1
	jr z,L_AEE1		;aed3
	dec a			;aed5
	ld (0e0a8h),a		;aed6   ; las vidas (0xE0A8)
	ld a,(0e0a8h)		;aed9   ; las vidas (0xE0A8)
	sla a		;aedc
	ld (0e0a9h),a		;aede   ; el aguante (0xE0A9, en medias)
L_AEE1:
	ld a,(0e00ah)		;aee1   ; la sala
	cp 002h		;aee4
	jr nc,L_AEF3		;aee6
	ld a,001h		;aee8
	ld (0e0a1h),a		;aeea
	ld (0e0a2h),a		;aeed
	jp sala_empieza		;aef0
L_AEF3:
	cp 002h		;aef3   ; 2?
	jr nz,L_AF04		;aef5
	ld a,001h		;aef7   ; la pantalla (1, 3)
	ld (0e0a1h),a		;aef9
	ld a,003h		;aefc
	ld (0e0a2h),a		;aefe
	jp sala_empieza		;af01   ; a la sala
L_AF04:
	cp 003h		;af04   ; 3?
	jr nz,L_AF13		;af06
	xor a			;af08   ; la pantalla (0, 1)
	ld (0e0a1h),a		;af09
	inc a			;af0c
	ld (0e0a2h),a		;af0d
	jp sala_empieza		;af10   ; a la sala
L_AF13:
	ld a,002h		;af13   ; si no: la pantalla (1, 2)
	ld (0e0a2h),a		;af15
	ld a,001h		;af18
	ld (0e0a1h),a		;af1a
	jp sala_empieza		;af1d   ; a la sala
L_AF20:
	call record_mira		;af20
	call puntos_pinta		;af23
	call ram_borra		;af26
	ld de,0194ch		;af29
	ld hl,05714h		;af2c
	ld bc,00009h		;af2f
	call 0005ch		;af32   ; LDIRVM
	ld a,001h		;af35
	call musica_pide		;af37   ; la musica
	call espera_musica		;af3a   ; hasta que acabe la musica
	xor a			;af3d
	ld (0e028h),a		;af3e
	ld (0e000h),a		;af41   ; jugando?
	ld (0e026h),a		;af44   ; el boton de empezar
	ld (0e0aah),a		;af47
	jp titulo		;af4a

; ----------------------------------------------------------------------
; DATOS continuar: CONTINUE PUSH TRIG1 (0xAF4D) y END      PUSH TRIG2 (0xAF60)
;   0xaf4d..0xaf73  (38 bytes)
DATA_continuar:
	defb 013h,01fh,01eh,024h,019h,01eh,025h,015h,010h,020h,025h,023h,018h,010h,024h,022h	; af4d  ...$..%.. %#..$"
	defb 019h,017h,001h,015h,01eh,014h,010h,010h,010h,010h,010h,010h,020h,025h,023h,018h	; af5d  ............ %#.
	defb 010h,024h,022h,019h,017h,002h	; af6d

; ======================================================================
; CODIGO 0xaf73..0xafa3  (48 bytes)
; ======================================================================


sala_acabada:		; La sala acabada (0xE186 = 2): todo fuera, la pantalla se cierra, el aguante lleno (0xE0A9 = vidas x 2), los puntos y la sala siguiente; tras la 4, la 0 y una vuelta mas (0xE009)
	call objetos_fuera		;af73   ; todo fuera
	call pantalla_cierra		;af76
	xor a			;af79
	ld (0e011h),a		;af7a   ; la cuenta de cuadros
	ld (0e0aah),a		;af7d
	ld a,(0e0a8h)		;af80   ; las vidas (0xE0A8)
	sla a		;af83
	ld (0e0a9h),a		;af85   ; el aguante (0xE0A9, en medias)
	call puntos_pinta		;af88
	ld hl,0e00ah		;af8b
	inc (hl)			;af8e
	ld a,(hl)			;af8f
	cp 005h		;af90
	jp c,L_AEE1		;af92
	xor a			;af95
	ld (0e00ah),a		;af96   ; la sala
	ld a,(0e009h)		;af99
	inc a			;af9c
	ld (0e009h),a		;af9d
	jp L_AEE1		;afa0

; ----------------------------------------------------------------------
; DATOS sobra_afa3: 19 bytes de codigo que nadie ejecuta (si un objeto se sale
;   de la pantalla, fuera); ningun salto llega
;   0xafa3..0xafb6  (19 bytes)
DATA_sobra_afa3:
	defb 0fdh,07eh,000h,0feh,00ch,038h,00ch,0feh,0a8h,030h,008h,0fdh,07eh,001h,0feh,0f6h	; afa3  .~...8...0..~...
	defb 030h,001h,0c9h	; afb3

; ======================================================================
; CODIGO 0xafb6..0xb6c7  (1809 bytes)
; ======================================================================


otro_borra:		; Los 16 bytes del objeto IY a cero, y fuera (Y 0xEC)
	push iy		;afb6   ; su principio
	pop hl			;afb8   ; su principio
	ld b,010h		;afb9   ; 16 bytes
otro_borra_byte:
	ld (hl),000h		;afbb   ; a cero
	inc hl			;afbd
	djnz otro_borra_byte		;afbe
	ld (iy+000h),0ech		;afc0   ; fuera
	ret			;afc4   ; listo
cerca_prota:		; ¿Toca? Segun lo que lleve (+0x1D, mas alto) y si esta agachado (+4): cerca_y o la comparacion de abajo
	ld a,(ix+004h)		;afc5   ; lleva algo?
	and a			;afc8
	jr nz,cerca_agachado		;afc9   ; si
cerca_y:		; ¿Toca en Y? A = la Y de IY menos la del protagonista (IX): C si queda entre B y C (con signo, de B a C)
	ld a,(iy+000h)		;afcb   ; la Y del otro...
	sub (ix+000h)		;afce   ; ...menos la del protagonista
cerca_mira:
	cp b			;afd1   ; por debajo de B: no
	ret c			;afd2   ; no
	cp c			;afd3   ; por debajo de C: si
	jr c,cerca_no		;afd4
	scf			;afd6   ; C: toca
	ret			;afd7   ; C: toca
cerca_no:
	and a			;afd8   ; NC: no
	ret			;afd9   ; NC
cerca_agachado:		; Agachado: la Y de IY menos la del protagonista entre B y 0xFA
	ld a,(iy+000h)		;afda   ; la X
	sub (ix+000h)		;afdd   ; la Y del protagonista
	cp b			;afe0
	ret c			;afe1
	cp 0fch		;afe2   ; 0xFA?
	jr c,cerca_no		;afe4
	scf			;afe6
	ret			;afe7
cerca_x:		; ¿Toca en X? La X de IY menos la del protagonista entre B y C
	ld a,(iy+001h)		;afe8
	sub (ix+001h)		;afeb   ; su X
	jr cerca_mira		;afee
arma_cerca_y:		; ¿El arma toca en Y?
	ld a,(iy+000h)		;aff0
	sub (ix+020h)		;aff3   ; la Y del arma
	jr cerca_mira		;aff6
arma_cerca_x:		; ¿El arma toca en X?
	ld a,(iy+001h)		;aff8
	sub (ix+021h)		;affb   ; la X del arma
	jr cerca_mira		;affe
sprites_ram:		; Los 16 objetos de 0xE300 (16 bytes: los 4 primeros son sus atributos) a 0xE100
	ld hl,0e300h		;b000   ; los objetos...
	ld de,0e100h		;b003   ; ...a 0xE100
	ld b,010h		;b006   ; 16
sprites_ram_uno:
	push bc			;b008
	ld bc,00004h		;b009   ; cuatro bytes
	ldir		;b00c   ; los atributos
	ld bc,0000ch		;b00e   ; el siguiente (+16)
	add hl,bc			;b011
	pop bc			;b012
	djnz sprites_ram_uno		;b013   ; 16
	ret			;b015
pantalla_limpia:		; La pantalla apagada, la tabla de nombres a 0x10, la RAM de 0xE100 a cero, el tiempo a 1100, los botones a 0, los dibujos y colores de las casillas (0x6180 / 0x7180, o 0x6980 / 0x7980 desde la escena 4) en los tres tercios; en la escena 0, otros dibujos (0x60C0, 0x70C0) en las casillas 0x34-0x3B, 0x50-0x59 y 0x90-0x95; y los de los sprites
	call 00041h		;b016   ; DISSCR
	call nombres_borra		;b019   ; la tabla de nombres
pantalla_limpia2:		; La RAM a cero y los botones a 0 (sin borrar la pantalla)
	call ram_borra		;b01c
	xor a			;b01f   ; los botones a 0
	ld (0e026h),a		;b020   ; los botones a 0
	ld (0e020h),a		;b023   ; el boton 2
	ld (0e022h),a		;b026   ; el boton 1
	ld (0e024h),a		;b029   ; 0xE024
	ld (0e180h),a		;b02c   ; la palanca
casillas_todas:		; Los dibujos y colores de las casillas 0x30-0xFF en los tres tercios, y los de los sprites
	ld de,00180h		;b02f   ; los dibujos, en los tres tercios...
	call casillas_pon		;b032   ; en el primer tercio
	ld de,00980h		;b035
	call casillas_pon		;b038
	ld de,01180h		;b03b
	call casillas_pon		;b03e
	ld de,02180h		;b041
	call colores_pon		;b044
	ld de,02980h		;b047
	call colores_pon		;b04a
	ld de,03180h		;b04d
	call colores_pon		;b050
	jp sprites_dibujos		;b053
marcador:		; HISCORE: (0x5705) en la fila 0, columna 17, SCORE en la 1, el aguante y los puntos
	ld de,01811h		;b056
	ld hl,05705h		;b059
	ld bc,0000fh		;b05c
	call 0005ch		;b05f   ; LDIRVM
	ld de,01833h		;b062
	ld hl,05707h		;b065
	ld bc,0000dh		;b068
	call 0005ch		;b06b   ; LDIRVM
	ld hl,01ac0h		;b06e
	ld bc,00020h		;b071
	ld a,060h		;b074
	call 00056h		;b076   ; FILVRM
	ret			;b079
vida_pinta:		; El aguante: las filas 0 y 1 desde la columna 1 en blanco y sus casillas (0xE0A9 / 2 enteras y media)
	ld hl,01801h		;b07a
	ld bc,00007h		;b07d
	ld a,010h		;b080
	call 00056h		;b082   ; FILVRM
	ld hl,01821h		;b085
	ld bc,00007h		;b088
	call 00056h		;b08b   ; FILVRM
	ld a,(0e0a8h)		;b08e   ; las vidas (0xE0A8)
	and a			;b091
	ret z			;b092
	ld b,a			;b093
	ld hl,01801h		;b094
	ld a,062h		;b097
L_B099:
	call 0004dh		;b099   ; WRTVRM
	inc hl			;b09c
	djnz L_B099		;b09d
	ld hl,01821h		;b09f
	ld a,(0e0a8h)		;b0a2   ; las vidas (0xE0A8)
	ld b,a			;b0a5
	ld a,061h		;b0a6
L_B0A8:
	call 0004dh		;b0a8   ; WRTVRM
	inc hl			;b0ab
	djnz L_B0A8		;b0ac
vida_casillas:		; 0xE0A9 / 2 casillas 0x64 arriba y 0x63 abajo; con impar, media
	ld a,(0e0a9h)		;b0ae   ; el aguante (0xE0A9, en medias)
	and a			;b0b1   ; ninguna?
	ret z			;b0b2
	bit 0,a		;b0b3   ; impar?
	jr nz,L_B0D3		;b0b5
	srl a		;b0b7   ; la mitad
	ld b,a			;b0b9
	push bc			;b0ba
	ld hl,01801h		;b0bb   ; en la fila 0, columna 1
	ld a,064h		;b0be   ; la casilla 0x64
L_B0C0:
	call 0004dh		;b0c0   ; WRTVRM
	inc hl			;b0c3   ; la siguiente
	djnz L_B0C0		;b0c4   ; tantas
	pop bc			;b0c6
	ld hl,01821h		;b0c7   ; en la fila 1
	ld a,063h		;b0ca   ; la casilla 0x63
L_B0CC:
	call 0004dh		;b0cc   ; WRTVRM
	inc hl			;b0cf   ; la siguiente
	djnz L_B0CC		;b0d0   ; tantas
	ret			;b0d2
L_B0D3:
	srl a		;b0d3
	and a			;b0d5
	jr nz,L_B0E1		;b0d6
	ld a,063h		;b0d8
	ld hl,01821h		;b0da
	call 0004dh		;b0dd   ; WRTVRM
	ret			;b0e0
L_B0E1:
	ld b,a			;b0e1
	push bc			;b0e2
	ld hl,01801h		;b0e3
	ld a,064h		;b0e6
L_B0E8:
	call 0004dh		;b0e8   ; WRTVRM
	inc hl			;b0eb
	djnz L_B0E8		;b0ec
	pop bc			;b0ee
	ld hl,01821h		;b0ef
	ld a,063h		;b0f2
L_B0F4:
	call 0004dh		;b0f4   ; WRTVRM
	inc hl			;b0f7
	djnz L_B0F4		;b0f8
	call 0004dh		;b0fa   ; WRTVRM
	ret			;b0fd
vida_llena:		; El aguante lleno (0xE0A9 = las vidas, 0xE0A8, x 2), pintado, 0xE0AA a 0 y el efecto 3
	ld a,(0e0a8h)		;b0fe   ; las vidas (0xE0A8)
	sla a		;b101
	ld b,a			;b103
	ld a,(0e0a9h)		;b104   ; el aguante (0xE0A9, en medias)
	cp b			;b107
	ret z			;b108
	ld a,b			;b109
	ld (0e0a9h),a		;b10a   ; el aguante (0xE0A9, en medias)
	call vida_casillas		;b10d
	xor a			;b110
	ld (0e0aah),a		;b111
	ld a,003h		;b114
	call efecto_pide		;b116   ; el efecto de B y C
	ret			;b119
vida_media:		; Medio aguante mas (0xE0A9 + 1), si no esta lleno, con el sonido 1
	ld a,(0e0a9h)		;b11a   ; el aguante (0xE0A9, en medias)
	srl a		;b11d
	ld b,a			;b11f
	ld a,(0e0a8h)		;b120   ; las vidas (0xE0A8)
	cp b			;b123
	ret z			;b124
	ret c			;b125
	ld a,(0e0a9h)		;b126   ; el aguante (0xE0A9, en medias)
	inc a			;b129
	ld (0e0a9h),a		;b12a   ; el aguante (0xE0A9, en medias)
	call vida_casillas		;b12d
	ld a,001h		;b130
	call sonido_a_pide		;b132   ; el sonido del canal A
	ret			;b135
vida_resta:		; El aguante - 1, pintado, y el sonido 7
	ld a,(0e0a9h)		;b136   ; el aguante (0xE0A9, en medias)
	dec a			;b139
	ld (0e0a9h),a		;b13a   ; el aguante (0xE0A9, en medias)
	call vida_pinta		;b13d
	ld a,007h		;b140
	call sonido_a_pide		;b142   ; el sonido del canal A
	ret			;b145
golpe:		; Un golpe al protagonista: nada con las teclas del titulo, tocado o parpadeando; con aguante, medio menos y el parpadeo; sin el, la muerte
	ld a,(0e023h)		;b146   ; 0xE023 (las teclas del titulo): no pasa nada
	and a			;b149
	ret nz			;b14a
	ld a,(ix+01fh)		;b14b   ; tocado?
	and a			;b14e
	ret nz			;b14f
	ld a,(ix+01ah)		;b150   ; parpadeando?
	and a			;b153
	ret nz			;b154
	ld a,(0e0a9h)		;b155   ; el aguante (0xE0A9, en medias)
	and a			;b158   ; hay?
	jr z,L_B172		;b159
	call vida_resta		;b15b
	ld (ix+01ah),001h		;b15e   ; +0x1A = 1
	ld a,005h		;b162   ; el sonido 5
	call sonido_a_pide		;b164   ; el sonido del canal A
	ld a,(0e0a9h)		;b167   ; el aguante (0xE0A9, en medias)
	and a			;b16a
	ret nz			;b16b
	ld a,002h		;b16c
	ld (0e183h),a		;b16e
	ret			;b171
L_B172:
	ld a,001h		;b172
	ld (0e183h),a		;b174
	ret			;b177
ram_borra:		; 0x1000 bytes de 0xE100 a cero; y 16 objetos fuera
	ld hl,0e100h		;b178   ; desde 0xE100...
	ld bc,01000h		;b17b   ; ...0x1000 bytes
ram_borra_byte:
	ld (hl),000h		;b17e   ; ...a cero
	inc hl			;b180   ; el siguiente
	dec bc			;b181   ; uno menos
	ld a,c			;b182
	or b			;b183
	jr nz,ram_borra_byte		;b184
objetos_fuera:		; 16 objetos de 16 bytes desde 0xE300 fuera (Y 0xEC) y los sprites
	ld hl,0e300h		;b186   ; 16 objetos...
	ld de,00010h		;b189   ; 16 bytes cada uno
	ld b,010h		;b18c   ; 16
objetos_fuera_y:
	ld (hl),0ech		;b18e   ; ...fuera
	add hl,de			;b190   ; el siguiente
	djnz objetos_fuera_y		;b191   ; 16
	call sprites_ram		;b193   ; los sprites
	call sprites_vram_tabla		;b196
	ret			;b199
objetos_borra:		; Los 256 bytes de 0xE400 a cero
	ld hl,0e400h		;b19a
	ld b,000h		;b19d
L_B19F:
	ld (hl),000h		;b19f
	inc hl			;b1a1
	djnz L_B19F		;b1a2
	ret			;b1a4
enemigos_borra:		; Los 0xC0 bytes de 0xE340 a cero y sus 12 enemigos fuera
	ld hl,0e340h		;b1a5
	ld b,0c0h		;b1a8
L_B1AA:
	ld (hl),000h		;b1aa   ; a cero
	inc hl			;b1ac   ; el siguiente
	djnz L_B1AA		;b1ad
	ld hl,0e340h		;b1af   ; los 12 enemigos...
	ld de,00010h		;b1b2   ; ...de 16 en 16...
	ld b,00ch		;b1b5
L_B1B7:
	ld (hl),0ech		;b1b7   ; ...fuera
	add hl,de			;b1b9
	djnz L_B1B7		;b1ba
	call sprites_ram		;b1bc   ; los sprites
	call sprites_vram_tabla		;b1bf
	ret			;b1c2
pantalla_abre:		; La sala de la RAM a la pantalla desde los bordes hacia el centro
	ld hl,0e700h		;b1c3   ; la izquierda de la sala
	ld (0e1a8h),hl		;b1c6
	ld hl,0e71fh		;b1c9   ; la derecha
	ld (0e1aah),hl		;b1cc
	ld hl,01840h		;b1cf   ; ...y las dos en la VRAM (fila 2)
	ld (0e1ach),hl		;b1d2
	ld hl,0185fh		;b1d5   ; la columna 31 de la VRAM
	ld (0e1aeh),hl		;b1d8
	ld b,010h		;b1db   ; 16 pasos
L_B1DD:
	ld hl,(0e1a8h)		;b1dd   ; los punteros de este paso
	ld (0e1a0h),hl		;b1e0
	ld hl,(0e1aah)		;b1e3
	ld (0e1a2h),hl		;b1e6
	ld hl,(0e1ach)		;b1e9
	ld (0e1a4h),hl		;b1ec
	ld hl,(0e1aeh)		;b1ef
	ld (0e1a6h),hl		;b1f2
	ld c,014h		;b1f5   ; 24 filas
	xor a			;b1f7
	ld (0e010h),a		;b1f8   ; la cuenta de cuadros
L_B1FB:
	ld a,(0e010h)		;b1fb   ; la cuenta de cuadros
	cp 001h		;b1fe
	jr c,L_B1FB		;b200
	xor a			;b202   ; la cuenta a 0
	ld (0e010h),a		;b203   ; la cuenta de cuadros
pantalla_abre_fila:
	ld hl,(0e1a4h)		;b206   ; la de la izquierda
	ld de,(0e1a0h)		;b209
	ld a,(de)			;b20d   ; la casilla de la izquierda
	call 0004dh		;b20e   ; WRTVRM
	ld hl,(0e1a6h)		;b211   ; la de la derecha
	ld de,(0e1a2h)		;b214
	ld a,(de)			;b218   ; la de la derecha
	call 0004dh		;b219   ; WRTVRM
	ld hl,(0e1a4h)		;b21c   ; la fila siguiente
	ld de,00020h		;b21f   ; una fila abajo, en la VRAM
	add hl,de			;b222
	ld (0e1a4h),hl		;b223
	ld hl,(0e1a0h)		;b226
	add hl,de			;b229
	ld (0e1a0h),hl		;b22a
	ld hl,(0e1a6h)		;b22d
	add hl,de			;b230
	ld (0e1a6h),hl		;b231
	ld hl,(0e1a2h)		;b234
	add hl,de			;b237
	ld (0e1a2h),hl		;b238
	dec c			;b23b
	jr nz,pantalla_abre_fila		;b23c
	ld hl,(0e1a8h)		;b23e   ; la izquierda, una a la derecha...
	inc hl			;b241
	ld (0e1a8h),hl		;b242
	ld hl,(0e1aah)		;b245   ; ...y la derecha, una a la izquierda
	dec hl			;b248
	ld (0e1aah),hl		;b249
	ld hl,(0e1ach)		;b24c
	inc hl			;b24f
	ld (0e1ach),hl		;b250
	ld hl,(0e1aeh)		;b253
	dec hl			;b256
	ld (0e1aeh),hl		;b257
	djnz L_B1DD		;b25a
	ret			;b25c
pantalla_cierra_centro:		; La zona de juego se borra desde el centro hacia los lados
	ld hl,01850h		;b25d   ; la fila 2, columna 16
	ld (0e1a0h),hl		;b260
	ld b,010h		;b263   ; 16 pasos
	ld hl,0184fh		;b265   ; la columna 15
	ld (0e1a2h),hl		;b268
	ld de,00020h		;b26b   ; 32 por fila
	xor a			;b26e
	ld (0e010h),a		;b26f   ; la cuenta de cuadros
L_B272:
	ld c,014h		;b272   ; 20 filas
	ld hl,(0e1a0h)		;b274
	ld de,(0e1a2h)		;b277
L_B27B:
	ld a,(0e010h)		;b27b   ; la cuenta de cuadros
	cp 001h		;b27e   ; un cuadro?
	jr c,L_B27B		;b280
	xor a			;b282
	ld (0e010h),a		;b283   ; la cuenta de cuadros
L_B286:
	ld a,080h		;b286   ; en blanco
	call 0004dh		;b288   ; a la derecha
	ex de,hl			;b28b
	call 0004dh		;b28c   ; y a la izquierda
	push de			;b28f
	ld de,00020h		;b290   ; una fila abajo...
	add hl,de			;b293
	pop de			;b294
	ex de,hl			;b295
	push de			;b296
	ld de,00020h		;b297   ; ...las dos
	add hl,de			;b29a
	pop de			;b29b
	dec c			;b29c   ; una fila menos
	jr nz,L_B286		;b29d
	ld hl,(0e1a0h)		;b29f   ; la derecha, una mas
	inc hl			;b2a2
	ld (0e1a0h),hl		;b2a3
	ld de,(0e1a2h)		;b2a6   ; la izquierda, una menos
	dec de			;b2aa
	ld (0e1a2h),de		;b2ab
	djnz L_B272		;b2af   ; 12 pasos
	ret			;b2b1
pantalla_cierra:		; La zona de juego (filas 2-23) se borra columna a columna, de izquierda a derecha, una cada 2 cuadros
	ld hl,01840h		;b2b2   ; la fila 2, columna 0
	ld (0e1a0h),hl		;b2b5   ; apuntada
	ld b,020h		;b2b8   ; 32 columnas
	xor a			;b2ba   ; la cuenta a 0
	ld (0e010h),a		;b2bb   ; la cuenta de cuadros
	ld de,00020h		;b2be   ; una fila
pantalla_cierra_columna:
	ld c,014h		;b2c1   ; 22 filas
	ld hl,(0e1a0h)		;b2c3   ; la columna
pantalla_cierra_espera:
	ld a,(0e010h)		;b2c6   ; la cuenta
	cp 002h		;b2c9   ; 2 cuadros?
	jr c,pantalla_cierra_espera		;b2cb
	xor a			;b2cd   ; la cuenta a 0
	ld (0e010h),a		;b2ce   ; a 0
pantalla_cierra_fila:
	ld a,080h		;b2d1   ; el espacio
	call 0004dh		;b2d3   ; WRTVRM
	add hl,de			;b2d6   ; la fila siguiente
	dec c			;b2d7   ; una fila menos
	jr nz,pantalla_cierra_fila		;b2d8
	ld hl,(0e1a0h)		;b2da   ; la columna...
	inc hl			;b2dd   ; la columna siguiente
	ld (0e1a0h),hl		;b2de   ; ...apuntada
	djnz pantalla_cierra_columna		;b2e1
	ret			;b2e3
nombres_borra:		; La tabla de nombres llena de la casilla 0x10 (el espacio)
	ld a,010h		;b2e4   ; el espacio...
	ld hl,01800h		;b2e6   ; ...en la tabla de nombres...
	ld bc,00300h		;b2e9   ; ...0x300 casillas
	call 00056h		;b2ec   ; FILVRM
	ret			;b2ef
letras_pon:		; La fuente de la BIOS (0x1D3F, 0x180 bytes) a DE; y DE al tercio siguiente
	push bc			;b2f0
	ld hl,01d3fh		;b2f1
	ld bc,00180h		;b2f4
L_B2F7:
	call 0005ch		;b2f7   ; LDIRVM
	ld bc,00800h		;b2fa
L_B2FD:
	add hl,bc			;b2fd
	ex de,hl			;b2fe
	pop bc			;b2ff
	ret			;b300
casillas_pon:		; Los dibujos de las casillas 0x30-0xFF (0x6000)
	push bc			;b301
	ld hl,06000h		;b302
	ld bc,00680h		;b305
	jr L_B2F7		;b308
colores_pon:		; Sus colores (0x7000)
	push bc			;b30a
	ld hl,07000h		;b30b
	ld bc,00680h		;b30e
	jr L_B2F7		;b311
fila_16:		; 16 casillas de HL a DE y DE a la fila siguiente
	push bc			;b313
	ld bc,00010h		;b314
	call 0005ch		;b317   ; LDIRVM
	ld bc,00020h		;b31a
	jr L_B2FD		;b31d
colores_ocho:		; 8 bytes de colores a A en HL; y HL al tercio siguiente
	push bc			;b31f
	ld bc,00008h		;b320   ; 8 bytes
L_B323:
	call 00056h		;b323   ; FILVRM
	ld de,00800h		;b326   ; al tercio siguiente
	add hl,de			;b329   ; al tercio siguiente
	pop bc			;b32a
	ret			;b32b
colores_titulo:		; 0x280 bytes de 0xF0 en los colores
	push bc			;b32c
	ld bc,00280h		;b32d
	ld a,0f0h		;b330
	jr L_B323		;b332
titulo_casillas:		; Las casillas del nombre: 0x6700 (0x100), 0x6E80 (0x180), 0x6680 y 0x7680
	push bc			;b334
	ld hl,06700h		;b335
	ld bc,00100h		;b338
	call 0005ch		;b33b   ; LDIRVM
	ld bc,00100h		;b33e
	add hl,bc			;b341
	ex de,hl			;b342
	ld hl,06e80h		;b343
	ld bc,00180h		;b346
	call 0005ch		;b349   ; LDIRVM
	ld bc,00700h		;b34c
	add hl,bc			;b34f
	ex de,hl			;b350
	pop bc			;b351
	djnz titulo_casillas		;b352
	ld de,01480h		;b354
	ld hl,06680h		;b357
	ld bc,00080h		;b35a
	call 0005ch		;b35d   ; LDIRVM
	ld de,03480h		;b360
	ld hl,07680h		;b363
	ld bc,00080h		;b366
	call 0005ch		;b369   ; LDIRVM
	ret			;b36c
sprites_dibujos:		; Los dibujos de los sprites (0x5800, 0x800 bytes) a 0x3800
	ld de,03800h		;b36d
	ld hl,05800h		;b370
	ld bc,00800h		;b373
	jp 0005ch		;b376   ; LDIRVM
sonido_reinicia:		; 0xE097 = 0xFF: la interrupcion pone el sonido a cero
	ld a,0ffh		;b379
	ld (0e097h),a		;b37b
	ret			;b37e
prota_sprites:		; Los cuatro sprites del protagonista a la tabla de atributos
	ld hl,0e300h		;b37f
	ld de,0e100h		;b382
	ld b,004h		;b385
	call sprites_ram_uno		;b387
sprites_vram_tabla:		; Los atributos de 0xE100 a la VRAM (0x1B00, 0x40 bytes)
	ld de,01b00h		;b38a   ; la tabla de atributos
	ld hl,0e100h		;b38d   ; desde 0xE100
	ld bc,00040h		;b390   ; 0x40 bytes
	call 0005ch		;b393   ; LDIRVM
	ret			;b396
puntos_pinta:		; Las seis cifras de los puntos (0xE001) en la fila 1 y del record (0xE02E) en la fila 0, columna 18
	ld hl,0e001h		;b397   ; los puntos
	ld de,01839h		;b39a   ; la fila 1, columna 18
	ld bc,00006h		;b39d
	call 0005ch		;b3a0   ; LDIRVM
	ld hl,0e08eh		;b3a3
	ld de,01819h		;b3a6   ; la fila 0, columna 25
	ld bc,00006h		;b3a9   ; seis
	jp 0005ch		;b3ac   ; LDIRVM
puntos_suma:		; Jugando, los puntos + A (BCD, las dos ultimas cifras, 0xE00E) con su acarreo; cada 10.000 (100.000 en pantalla) una vida mas; al pasar de 999999 el record se queda con los puntos; desde 5.000 (0xE00D 0x50; en pantalla 50.000), una vida mas, una vez (0xE04F); y las cifras y el record
	ld b,a			;b3af   ; lo que se suma
	ld a,(0e000h)		;b3b0   ; jugando?
	and a			;b3b3
	ret z			;b3b4   ; no: nada
	ld a,(0e00eh)		;b3b5   ; las dos ultimas
	add a,b			;b3b8
	daa			;b3b9   ; en BCD
	ld (0e00eh),a		;b3ba   ; apuntadas
	jr nc,L_B3EB		;b3bd   ; sin acarreo
	ld a,001h		;b3bf   ; acarreo
puntos_suma_cien:
	ld b,a			;b3c1
	ld a,(0e00dh)		;b3c2   ; las centenas
	add a,b			;b3c5
	daa			;b3c6
	ld (0e00dh),a		;b3c7   ; apuntadas
	jr nc,L_B3EB		;b3ca
	ld a,001h		;b3cc   ; acarreo
	ld b,a			;b3ce   ; 1
	ld a,(0e00ch)		;b3cf   ; las decenas de millar
	add a,b			;b3d2
	daa			;b3d3   ; en BCD
	ld (0e00ch),a		;b3d4   ; apuntadas
	jr nc,L_B3EB		;b3d7
	ld a,(0e00ch)		;b3d9   ; se pasa: el record = los puntos
	ld (0e094h),a		;b3dc
	ld a,(0e00dh)		;b3df
	ld (0e095h),a		;b3e2
	ld a,(0e00eh)		;b3e5
	ld (0e096h),a		;b3e8
L_B3EB:
	call puntos_cifras		;b3eb
	call record_mira		;b3ee
	ret			;b3f1
puntos_cifras:		; Los tres bytes BCD de los puntos (0xE00C) en seis cifras (0xE001), una por byte
	ld hl,0e001h		;b3f2   ; las cifras
	ld de,0e00ch		;b3f5   ; los bytes BCD
	ld b,003h		;b3f8   ; tres
cifras_bcd:		; B bytes BCD de DE a cifras en HL (dos por byte)
	ld a,(de)			;b3fa   ; un byte
	ld c,a			;b3fb   ; guardado
	and 0f0h		;b3fc   ; la cifra alta
	rrca			;b3fe
	rrca			;b3ff
	rrca			;b400
	rrca			;b401
	ld (hl),a			;b402   ; apuntada
	inc hl			;b403   ; la siguiente
	ld a,c			;b404   ; la baja
	and 00fh		;b405   ; la baja
	ld (hl),a			;b407   ; la baja
	inc hl			;b408   ; la siguiente
	inc de			;b409   ; el siguiente
	djnz cifras_bcd		;b40a   ; tres bytes
	ret			;b40c
record_mira:		; Si los puntos (0xE00C) pasan del record (0xE034), son el record nuevo y sus cifras (0xE02E)
	ld de,0e094h		;b40d   ; el record
	ld hl,0e00ch		;b410   ; los puntos
	ld a,(de)			;b413   ; el byte alto...
	ld b,a			;b414
	ld a,(hl)			;b415   ; ...contra el de los puntos
	cp b			;b416   ; menos: nada
	ret c			;b417   ; menor: nada
	jr nz,record_nuevo_3		;b418   ; mayor: record nuevo
	inc de			;b41a   ; iguales: el siguiente
	inc hl			;b41b
	ld a,(de)			;b41c   ; el siguiente
	ld b,a			;b41d
	ld a,(hl)			;b41e
	cp b			;b41f   ; menos?
	ret c			;b420   ; menor: nada
	jr nz,record_nuevo_2		;b421   ; mas: record
	inc de			;b423   ; el bajo
	inc hl			;b424
	ld a,(de)			;b425   ; el siguiente
	ld b,a			;b426
	ld a,(hl)			;b427
	cp b			;b428   ; menos?
	ret c			;b429   ; menor: nada
	jr record_nuevo		;b42a   ; igual o mas: record
record_nuevo_3:
	inc de			;b42c
	inc hl			;b42d
record_nuevo_2:
	inc de			;b42e
	inc hl			;b42f
record_nuevo:		; Los tres bytes, hacia atras
	ld bc,00003h		;b430   ; tres bytes...
	lddr		;b433   ; ...hacia atras
	ld hl,0e08eh		;b435   ; sus cifras
	ld de,0e094h		;b438
	ld b,003h		;b43b   ; tres bytes
	jr cifras_bcd		;b43d   ; sus cifras
espera_musica:		; Espera 8 cuadros, despues hasta que la musica acabe (0xE2BD y 0xE2BE a 0; en el titulo, el boton la corta) y despues 16 cuadros mas
	xor a			;b43f   ; la cuenta a 0
	ld (0e011h),a		;b440   ; la cuenta de cuadros
L_B443:
	ld a,(0e011h)		;b443   ; un cuadro mas
	cp 008h		;b446   ; 8?
	jr c,L_B443		;b448
L_B44A:
	call sprites_ram		;b44a   ; los sprites
	call sprites_vram_tabla		;b44d
	ld a,(0e000h)		;b450   ; jugando?
	and a			;b453
	jr nz,espera_musica_mira		;b454
	ld a,(0e026h)		;b456   ; el boton?
	and a			;b459
	ret nz			;b45a
espera_musica_mira:
	ld a,(0e2bdh)		;b45b   ; sonando?
	and a			;b45e
	jr nz,L_B44A		;b45f
	ld a,(0e2beh)		;b461
	and a			;b464
	jr nz,L_B44A		;b465
	ld (0e011h),a		;b467   ; la cuenta a 0
	call sonido_reinicia		;b46a   ; el sonido a cero
L_B46D:
	ld a,(0e011h)		;b46d   ; la cuenta de cuadros
	cp 010h		;b470
	jr c,L_B46D		;b472
	ret			;b474
L_B475:
	ld a,(0e097h)		;b475   ; se pidio el sonido a cero (0xE097)?
	cp 0ffh		;b478
	jr nz,interrupcion_sonido		;b47a
	call sonido_cero		;b47c   ; a cero
	xor a			;b47f   ; atendido
	ld (0e097h),a		;b480
interrupcion_sonido:
	ld a,(0e2bdh)		;b483   ; el canal de musica 1...
	ld b,a			;b486
	ld a,(0e2c1h)		;b487   ; ...y el 2
	add a,b			;b48a   ; sonando alguno?
	and a			;b48b   ; un efecto?
	jr nz,interrupcion_motor		;b48c
	ld e,000h		;b48e   ; sin efecto: los canales B y C a volumen 0
	ld a,009h		;b490   ; ...a volumen 0
	call 00093h		;b492   ; WRTPSG
	ld e,000h		;b495   ; el C...
	ld a,00ah		;b497   ; el registro 10
	call 00093h		;b499   ; ...WRTPSG
interrupcion_motor:
	call sonido		;b49c   ; el motor de sonido
	ld hl,0e010h		;b49f
	ld b,010h		;b4a2
L_B4A4:
	inc (hl)			;b4a4
	inc hl			;b4a5
	djnz L_B4A4		;b4a6
	ld a,(0e000h)		;b4a8   ; jugando?
	and a			;b4ab
	jr z,interrupcion_quieto		;b4ac
	ld a,006h		;b4ae   ; la fila 6: F1 (bit 5)?
	call 00141h		;b4b0   ; SNSMAT
	bit 5,a		;b4b3   ; F1?
	jr z,tecla_f1		;b4b5
	xor a			;b4b7   ; suelta
	ld (0e1b4h),a		;b4b8   ; suelta
	jr tecla_stop		;b4bb
tecla_f1:
	ld a,(0e1b4h)		;b4bd   ; ya sostenida?
	and a			;b4c0
	jr nz,tecla_stop		;b4c1   ; si: nada
	inc a			;b4c3   ; recien pulsada: el protagonista cae (0xE1B3)
	ld (0e1b3h),a		;b4c4   ; 0xE1B3 = 1
	ld (0e1b4h),a		;b4c7
tecla_stop:
	ld a,007h		;b4ca   ; la fila 7: STOP (bit 4)?
	call 00141h		;b4cc   ; SNSMAT
	bit 4,a		;b4cf   ; STOP?
	jr z,tecla_stop_pulsada		;b4d1
	xor a			;b4d3   ; suelta
	ld (0e1b6h),a		;b4d4   ; suelta
	jr botones		;b4d7
tecla_stop_pulsada:
	ld a,(0e1b6h)		;b4d9
	and a			;b4dc
	jr nz,botones		;b4dd
	inc a			;b4df   ; recien pulsada: 0xE1B5
	ld (0e1b5h),a		;b4e0
	ld (0e1b6h),a		;b4e3
botones:
	ld de,0e020h		;b4e6   ; el boton 2 del mando (GTTRIG 3)
	ld hl,0e021h		;b4e9   ; el boton 2 del mando (GTTRIG 3)
	ld a,003h		;b4ec
	call boton_mando		;b4ee
	ld de,0e022h		;b4f1
	ld hl,0e08dh		;b4f4
	ld a,001h		;b4f7
	call boton_mando		;b4f9
	ld de,0e020h		;b4fc
	ld hl,0e08bh		;b4ff
	call botones_teclado		;b502
palanca:		; La palanca: los cursores o el mando 1 (GTSTCK 0 y 1), en 0xE180
	xor a			;b505
	call 000d5h		;b506   ; GTSTCK 0: los cursores
	ld (0e181h),a		;b509
	ld a,001h		;b50c
	call 000d5h		;b50e   ; GTSTCK 1: el mando 1
	ld c,a			;b511
	ld a,(0e181h)		;b512
	or c			;b515   ; uno u otro
	ld (0e180h),a		;b516   ; la palanca
	ret			;b519
interrupcion_quieto:		; Fuera de partida: en la demostracion (0xE027), cada 16 cuadros una entrada de la lista de 0xE037 (desde 0x5200): la mitad baja la palanca, la alta los botones (0x10 el 1, 0x20 el 2, otra los dos); en el titulo, el boton de empezar (0xE026) y la palanca
	ld a,(0e028h)		;b51a   ; la demostracion?
	and a			;b51d   ; la demostracion?
	jr z,L_B553		;b51e
	ld a,(0e016h)		;b520   ; cada 16 cuadros
	cp 010h		;b523
	jr c,empezar_lee		;b525
	xor a			;b527   ; a cero
	ld (0e016h),a		;b528
	ld a,(0e027h)		;b52b   ; la demostracion?
	and a			;b52e
	jr z,empezar_lee		;b52f
	ld hl,(0e029h)		;b531   ; la lista (0xE029)...
	ld a,(hl)			;b534   ; ...un byte...
	inc hl			;b535   ; ...el siguiente
	ld (0e029h),hl		;b536
	ld b,a			;b539   ; guardado
	and 00fh		;b53a
	ld (0e180h),a		;b53c   ; la palanca
	ld a,b			;b53f
	and 0f0h		;b540
	and a			;b542
	jr z,empezar_lee		;b543
	cp 001h		;b545
	jr nz,L_B54E		;b547
	ld (0e020h),a		;b549   ; el boton 2
	jr empezar_lee		;b54c
L_B54E:
	ld (0e022h),a		;b54e   ; el boton 1
	jr empezar_lee		;b551
L_B553:
	call empezar_lee		;b553
	jr palanca		;b556
empezar_lee:		; El boton de empezar (0xE026): la barra o el boton 1 del mando
	ld de,0e026h		;b558
	ld hl,0e025h		;b55b
	call barra_lee		;b55e
	ld a,(de)			;b561
	ld (0e181h),a		;b562
	ld hl,0e021h		;b565
	ld a,001h		;b568
	call boton_mando		;b56a
	ld a,(de)			;b56d   ; ...o lo del mando
	ld b,a			;b56e
	ld a,(0e181h)		;b56f   ; una...
	or b			;b572   ; ...u otro
	ld (de),a			;b573
	ret			;b574
boton_mando:		; GTTRIG A: lo recien pulsado en (DE) y lo sostenido en (HL)
	call 000d8h		;b575   ; GTTRIG
	and a			;b578
boton_mira:
	jr nz,boton_pulsado		;b579   ; pulsado?
boton_suelto:
	ld (hl),000h		;b57b   ; suelto
	ret			;b57d
boton_pulsado:
	ld a,(hl)			;b57e   ; ya sostenido?
	and a			;b57f
	ret nz			;b580
	inc a			;b581   ; recien pulsado
	ld (hl),a			;b582   ; sostenido
	ld (de),a			;b583   ; recien pulsado
	ret			;b584
barra_lee:		; La barra (fila 8, bit 0): lo mismo
	ld a,008h		;b585   ; la fila 8...
	call 00141h		;b587   ; SNSMAT
	rrca			;b58a   ; el bit 0: pulsada = 0
	jr nc,boton_pulsado		;b58b
	jr boton_suelto		;b58d
botones_teclado:		; La barra como boton 1 y GRAPH (fila 6, bit 2) como boton 2
	ld a,006h		;b58f   ; la fila 6
	call 00141h		;b591   ; SNSMAT
	cpl			;b594   ; pulsada = 1
	bit 2,a		;b595   ; GRAPH (bit 2)
	call boton_mira		;b597
	inc hl			;b59a
	inc de			;b59b
	inc de			;b59c
	ld a,008h		;b59d
	call 00141h		;b59f   ; SNSMAT
	cpl			;b5a2
	bit 0,a		;b5a3
	jr boton_mira		;b5a5
presentacion:		; La presentacion de CASIO: cada 3 cuadros, dos CASIO entran por los lados (filas 11 y 12) y, desde el paso 9, otros dos bajan y suben hacia el centro; con el paso 21, la musica 4 y SOFTWARE (0x8B14) debajo; 128 cuadros o el boton y la pantalla en blanco
	ld a,001h		;b5a7   ; el paso 1
	ld (0e187h),a		;b5a9
	ld hl,0180ch		;b5ac   ; el que baja: la fila 0, columna 12
	ld (0e189h),hl		;b5af
	ld hl,01aech		;b5b2   ; el que sube: la fila 23
	ld (0e18bh),hl		;b5b5
presentacion_cuadro:
	ld a,(0e014h)		;b5b8   ; 3 cuadros
	cp 003h		;b5bb
	jr c,presentacion_cuadro		;b5bd
	xor a			;b5bf
	ld (0e014h),a		;b5c0   ; en la cuenta de cuadros
	call presentacion_vert		;b5c3   ; el de arriba y el de abajo
	call presentacion_lados		;b5c6
	ld hl,0e187h		;b5c9   ; un paso mas
	inc (hl)			;b5cc
	ld a,(hl)			;b5cd
	cp 015h		;b5ce   ; 21?
	jr nc,presentacion_junta		;b5d0
	cp 009h		;b5d2   ; desde el 9...
	jr c,presentacion_sigue		;b5d4
	ld hl,(0e189h)		;b5d6   ; ...el de arriba baja una fila...
	ld bc,00020h		;b5d9
	add hl,bc			;b5dc
	ld (0e189h),hl		;b5dd
	ld hl,(0e18bh)		;b5e0   ; ...y el de abajo sube
	sbc hl,bc		;b5e3
	ld (0e18bh),hl		;b5e5
presentacion_sigue:
	jr presentacion_cuadro		;b5e8
presentacion_junta:
	ld a,004h		;b5ea   ; la musica 4
	call musica_pide		;b5ec   ; pide la musica
L_B5EF:
	ld a,(0e014h)		;b5ef   ; la cuenta de cuadros
	cp 080h		;b5f2
	jr c,L_B5EF		;b5f4
	xor a			;b5f6
	ld (0e026h),a		;b5f7   ; el boton de empezar
	call sonido_reinicia		;b5fa
	call nombres_borra		;b5fd
	ret			;b600
presentacion_vert:		; Desde el paso 9: el CASIO que baja y el que sube
	ld a,(0e187h)		;b601
	cp 009h		;b604
	ret c			;b606
	ld bc,00008h		;b607
	ld hl,0b6d1h		;b60a
	ld de,(0e189h)		;b60d
	call 0005ch		;b611   ; LDIRVM
	ld de,00020h		;b614
	and a			;b617
	sbc hl,de		;b618
	ex de,hl			;b61a
	ld hl,0b6c8h		;b61b
	ld bc,00008h		;b61e
	call 0005ch		;b621   ; LDIRVM
	ld de,00020h		;b624
	and a			;b627
	sbc hl,de		;b628
	ex de,hl			;b62a
	ld hl,0b6dah		;b62b
	ld bc,00008h		;b62e
	call 0005ch		;b631   ; LDIRVM
	ld bc,00008h		;b634
	ld hl,0b6c8h		;b637
	ld de,(0e18bh)		;b63a
	call 0005ch		;b63e   ; LDIRVM
	ld de,00020h		;b641
	add hl,de			;b644
	ex de,hl			;b645
	ld hl,0b6d1h		;b646
	ld bc,00008h		;b649
	call 0005ch		;b64c   ; LDIRVM
	ld de,00020h		;b64f
	add hl,de			;b652
	ex de,hl			;b653
	ld hl,0b6dah		;b654
	ld bc,00008h		;b657
	call 0005ch		;b65a   ; LDIRVM
	ret			;b65d
presentacion_lados:		; Los dos CASIO de los lados en las filas 11 y 12: uno entra por la derecha casilla a casilla y el otro por la izquierda, leido desde el final
	ld a,(0e187h)		;b65e   ; el paso
	ld c,a			;b661
	cp 009h		;b662   ; ...no mas de 9
	jr c,presentacion_arriba		;b664
	ld c,009h		;b666   ; 9 como mucho
presentacion_arriba:
	ld hl,01980h		;b668   ; en la fila 12, columna 0, menos el paso
	ld b,a			;b66b   ; la columna, hacia la izquierda
	ld a,l			;b66c
	sub b			;b66d
	ld l,a			;b66e
	ex de,hl			;b66f
	ld hl,0b6c8h		;b670   ; la fila de arriba de CASIO...
	ld b,000h		;b673
	call 0005ch		;b675   ; LDIRVM
	ld de,00020h		;b678
	add hl,de			;b67b
	ex de,hl			;b67c
	ld hl,0b6d1h		;b67d
	ld a,(0e187h)		;b680
	cp 009h		;b683
	jr c,presentacion_arriba_pon		;b685
	ld a,009h		;b687
presentacion_arriba_pon:
	ld c,a			;b689   ; C casillas
	call 0005ch		;b68a   ; LDIRVM
	ld hl,01960h		;b68d   ; el otro: la fila 11
	ld a,(0e187h)		;b690
	ld c,a			;b693
	cp 009h		;b694   ; 9 o mas?
	jr c,presentacion_izq		;b696
	sub 009h		;b698   ; pasado el 9, se mueve
	add a,l			;b69a
	ld l,a			;b69b
	ld c,009h		;b69c   ; 9
presentacion_izq:
	ex de,hl			;b69e   ; DE: la VRAM
	ld hl,0b6d0h		;b69f   ; la fila de arriba, desde el final
	ld a,l			;b6a2
	sub c			;b6a3   ; - C
	jr nc,presentacion_izq_pon		;b6a4
	dec h			;b6a6
presentacion_izq_pon:
	ld l,a			;b6a7
	call 0005ch		;b6a8   ; LDIRVM
	ld de,00020h		;b6ab   ; una fila abajo
	add hl,de			;b6ae
	ex de,hl			;b6af
	ld a,(0e187h)		;b6b0   ; el paso
	ld c,a			;b6b3
	cp 009h		;b6b4
	jr c,presentacion_izq_abajo		;b6b6
	ld c,009h		;b6b8
presentacion_izq_abajo:
	ld hl,0b6d9h		;b6ba
	ld a,l			;b6bd
	sub c			;b6be
	jr nc,L_B6C2		;b6bf
	dec h			;b6c1
L_B6C2:
	ld l,a			;b6c2
	call 0005ch		;b6c3   ; LDIRVM
	ret			;b6c6

; ----------------------------------------------------------------------
; DATOS casio_filas: Las filas de CASIO de la presentacion
;   0xb6c7..0xb6e2  (27 bytes)
DATA_casio_filas:
	defb 010h,080h,082h,084h,086h,088h,08ah,08ch,08eh,010h,081h,083h,085h,087h,089h,08bh	; b6c7  ................
	defb 08dh,08fh,010h,010h,010h,010h,010h,010h,010h,010h,010h	; b6d7  ...........

; ----------------------------------------------------------------------
; DATOS sobra_b6e2: 30 bytes de relleno (FB 00) que nadie lee
;   0xb6e2..0xb700  (30 bytes)
DATA_sobra_b6e2:
	defb 010h,010h,000h,0fbh,000h,0fbh,000h,0fbh,000h,0fbh,000h,0fbh,000h,0fbh,0ffh,000h	; b6e2  ................
	defb 0fbh,000h,0fbh,000h,0fbh,000h,0fbh,000h,0fbh,000h,0fbh,000h,0fbh,000h	; b6f2  ..............

; ----------------------------------------------------------------------
; DATOS musicas: Las 8 musicas: las piezas de los canales A, B y C (6 bytes
;   cada una; la 0, nada)
;   0xb700..0xb730  (48 bytes)
DATA_musicas:
	defb 0ach,0bbh,0ach,0bbh,0ach,0bbh,0b0h,0bbh,0c6h,0bbh,0dfh,0bbh,0f8h,0bbh,01ch,0bch	; b700  ................
	defb 03eh,0bch,05ah,0bch,09fh,0bch,0bch,0bch,0d4h,0bch,0d8h,0bch,0dch,0bch,0e2h,0bch	; b710  >.Z.............
	defb 0e6h,0bch,0eah,0bch,0f0h,0bch,018h,0bdh,035h,0bdh,056h,0bdh,053h,0bdh,098h,0bdh	; b720  ........5.V.S...

; ----------------------------------------------------------------------
; DATOS efectos_a: Los 8 efectos del canal A: su pieza (2 bytes)
;   0xb730..0xb740  (16 bytes)
DATA_efectos_a:
	defb 036h,0bbh,03ah,0bbh,075h,0bbh,040h,0bbh,056h,0bbh,087h,0bbh,097h,0bbh,0a5h,0bbh	; b730  6.:.u.@.V.......

; ----------------------------------------------------------------------
; DATOS efectos_bc: Los 6 efectos de los canales B y C: sus dos piezas (4
;   bytes)
;   0xb740..0xb758  (24 bytes)
DATA_efectos_bc:
	defb 0ach,0bbh,0ach,0bbh,0e6h,0bdh,0f6h,0bdh,008h,0beh,014h,0beh,048h,0beh,05bh,0beh	; b740  ............H.[.
	defb 06eh,0beh,0f4h,0beh,018h,0bfh,0b3h,0bfh	; b750  n.......

; ======================================================================
; CODIGO 0xb758..0xba2d  (725 bytes)
; ======================================================================


sonido_a_pide:		; Pide el efecto A del canal A (0xE2C0); gana el de numero menor. Donde otros Casio llevan "ret z" (sin partida, nada), aqui hay un "nop": suena tambien en la demostracion
	ld b,a			;b758   ; el numero
	ld a,(0e000h)		;b759   ; jugando...
	and a			;b75c
	ret z			;b75d
sonido_a_pon:
	ld a,b			;b75e   ; el efecto
	ld hl,0e2c0h		;b75f   ; el efecto del canal A pedido
	jr pide_va		;b762
efecto_pide:		; Pide el efecto A (0xE2C2), solo en partida: si ya hay uno, se queda el de numero mas bajo
	ld b,a			;b764   ; el numero
	ld a,(0e000h)		;b765   ; en partida?
	and a			;b768
	ret z			;b769
	ld a,b			;b76a   ; el efecto
	ld hl,0e2c2h		;b76b   ; el efecto pedido
pide_va:
	ld b,a			;b76e
	ld a,(hl)			;b76f   ; ya hay uno?
	and a			;b770
	jr z,pide_pon		;b771
	cp b			;b773   ; el de antes es menor: se queda
	ret c			;b774
pide_pon:
	ld (hl),b			;b775   ; el nuevo
	ret			;b776
musica_pide:		; Pide la musica A (0xE2BE), con la misma regla
	ld hl,0e2beh		;b777   ; la musica pedida
	jr pide_va		;b77a
sonido:		; El sonido de cada cuadro (desde la interrupcion): una musica nueva o un efecto nuevo empiezan; los tres canales (0xE280, 0xE292, 0xE2A4, 18 bytes) siguen
	ld hl,0e2bdh		;b77c   ; una musica sonando?
	xor a			;b77f
	cp (hl)			;b780   ; sonando?
	jr nz,L_B79B		;b781
	inc hl			;b783   ; una pedida?
	cp (hl)			;b784
	jp nz,musica_empieza		;b785   ; empieza
	inc hl			;b788
	cp (hl)			;b789
	jr nz,L_B7A3		;b78a
	inc hl			;b78c
	cp (hl)			;b78d
	jp nz,efecto_a_empieza		;b78e
L_B791:
	xor a			;b791   ; nada en el canal A...
	inc hl			;b792   ; el efecto de B y C?
	cp (hl)			;b793
	jr nz,L_B7AB		;b794   ; sonando
	inc hl			;b796   ; pedido?
	cp (hl)			;b797
	jp nz,L_BAD6		;b798
L_B79B:
	call pedido_mira		;b79b
	jp c,musica_empieza		;b79e
	jr sonido_canal_a		;b7a1
L_B7A3:
	call pedido_mira		;b7a3
	jp c,efecto_a_empieza		;b7a6
	jr L_B791		;b7a9
L_B7AB:
	call pedido_mira		;b7ab
	jp c,L_BAD6		;b7ae
sonido_canal_a:		; El canal A: su bloque a 0xE2C3, un paso y de vuelta
	ld a,(0e2bdh)		;b7b1   ; la musica?
	and a			;b7b4
	jr nz,sonido_canal_a_va		;b7b5
	ld a,(0e2bfh)		;b7b7   ; o un efecto que use el canal A?
	and a			;b7ba
	jr z,sonido_canal_b		;b7bb
sonido_canal_a_va:
	ld hl,0e280h		;b7bd   ; el canal A
	call canal_a_trabajo		;b7c0   ; al canal de trabajo
	ld bc,00008h		;b7c3
	xor a			;b7c6
	call canal_un_paso		;b7c7
	push af			;b7ca
	ld de,0e280h		;b7cb
	call canal_de_trabajo		;b7ce
	pop af			;b7d1
	and a			;b7d2
	jr z,sonido_canal_b		;b7d3
	cp 001h		;b7d5
	jp z,musica_acaba		;b7d7
	cp 002h		;b7da
	jp z,sonido_a_acaba		;b7dc
sonido_canal_b:		; Los canales B y C: con la musica o el efecto de B y C, un paso de cada uno (los registros 2-3 y 9, 4-5 y 10); al acabar, sonido_bc_acaba
	ld a,(0e2bdh)		;b7df   ; la musica?
	and a			;b7e2
	jr nz,sonido_canal_b_va		;b7e3
	ld a,(0e2c1h)		;b7e5   ; o el efecto de B y C?
	and a			;b7e8
	ret z			;b7e9
sonido_canal_b_va:
	ld hl,0e292h		;b7ea   ; el canal B
	call canal_a_trabajo		;b7ed
	ld bc,00209h		;b7f0
	ld a,(0e088h)		;b7f3
	rrca			;b7f6
	ld (0e088h),a		;b7f7
	ld a,001h		;b7fa
	call canal_un_paso		;b7fc
	push af			;b7ff
	ld de,0e292h		;b800
	call canal_de_trabajo		;b803
	pop af			;b806
	cp 003h		;b807   ; 3: sigue
	jr z,L_B818		;b809
	ld b,a			;b80b
	ld a,(0e088h)		;b80c   ; los bits de vuelta
	rlca			;b80f
	ld (0e088h),a		;b810
	ld a,b			;b813
	and a			;b814
	jp nz,sonido_bc_acaba		;b815   ; acabado
L_B818:
	ld hl,0e2a4h		;b818   ; el canal C
	call canal_a_trabajo		;b81b
	ld bc,0040ah		;b81e   ; los registros 4 y 10
	ld a,(0e088h)		;b821
	rrca			;b824
	rrca			;b825
	ld (0e088h),a		;b826
	ld a,002h		;b829   ; el canal 2
	call canal_un_paso		;b82b
	push af			;b82e
	ld de,0e2a4h		;b82f   ; de vuelta
	call canal_de_trabajo		;b832
	pop af			;b835
	cp 003h		;b836   ; 3: sigue
	jp z,ruido_barrido		;b838
	ld b,a			;b83b
	ld a,(0e088h)		;b83c
	rlca			;b83f
	rlca			;b840
	ld (0e088h),a		;b841
	ld a,b			;b844
	and a			;b845
	jp nz,sonido_bc_acaba		;b846
	jp ruido_barrido		;b849
canal_a_trabajo:		; Copia el bloque del canal (HL, 18 bytes) a 0xE2C3
	ld de,0e2c3h		;b84c   ; al canal de trabajo
copia18:
	ld bc,00012h		;b84f   ; 18 bytes
	ldir		;b852   ; copiados
	ret			;b854
canal_de_trabajo:		; Y de vuelta a DE
	ld hl,0e2c3h		;b855
	jr copia18		;b858
canal_paso:		; Un paso del canal de trabajo: si la nota sigue, nada; si no, el byte siguiente de la pieza: una nota (menos de 0xF0) o una orden
	ld hl,0e2cdh		;b85a   ; la nota sigue?
	ld a,(hl)			;b85d
	and a			;b85e
	jr z,canal_byte		;b85f
	call canal_cuenta		;b861   ; su cuenta
	and a			;b864
	ret z			;b865
canal_byte:		; El byte siguiente de la pieza (0xE2C3): menos de 0xF0, una nota (duracion y volumen, el tono) y 3; si no, una orden
	ld iy,0e2cdh		;b866
	ld hl,(0e2c3h)		;b86a
	ld a,(hl)			;b86d   ; el byte
	cp 0f0h		;b86e   ; 0xF0 o mas: una orden
	jr nc,L_B897		;b870
	call nota_pon		;b872
	call nota_tono		;b875
	ld (0e2c3h),hl		;b878   ; apuntado
	ld a,(0e088h)		;b87b   ; el canal con tono, sin ruido
	res 0,a		;b87e
	set 3,a		;b880
canal_mezcla:
	ld c,a			;b882   ; guardado
	ld a,(0e2d5h)		;b883   ; corrido al canal
	and a			;b886
	ld b,a			;b887
	ld a,c			;b888
	jr z,canal_mezcla_pon		;b889
canal_mezcla_corre:
	rlca			;b88b
	djnz canal_mezcla_corre		;b88c   ; B veces
canal_mezcla_pon:
	ld (0e088h),a		;b88e   ; el registro 7
	call psg_mezcla		;b891
	ld a,003h		;b894
	ret			;b896
L_B897:
	jp z,canal_ruido		;b897
	cp 0ffh		;b89a   ; 0xFF: el final
	jr nz,canal_orden_f7		;b89c
	ld a,001h		;b89e   ; 1
	ret			;b8a0
canal_orden_f7:
	cp 0f7h		;b8a1   ; 0xF7: callar
	jr nz,canal_orden_fe		;b8a3
	ld a,002h		;b8a5   ; 2
	ret			;b8a7
canal_orden_fe:
	cp 0feh		;b8a8   ; 0xFE: al principio
	jr nz,canal_orden_fd		;b8aa
	ld hl,(0e2c5h)		;b8ac   ; la pieza otra vez desde su principio
	jr canal_orden_sigue		;b8af
canal_orden_fd:		; 0xFD n: la marca 1 y cuantas veces
	cp 0fdh		;b8b1   ; 0xFD n: el primer bucle, n veces
	jr nz,canal_orden_fc		;b8b3
	inc hl			;b8b5   ; cuantas veces...
	ld a,(hl)			;b8b6
	ld (iy+005h),a		;b8b7   ; ...en +5
	inc hl			;b8ba
	ld (0e2c7h),hl		;b8bb   ; la marca 1
	jr canal_orden_sigue		;b8be
canal_orden_fc:		; 0xFC: vuelve a la marca 1 si quedan
	cp 0fch		;b8c0   ; 0xFC: el final del primer bucle
	jr nz,canal_orden_fb		;b8c2
	dec (iy+005h)		;b8c4   ; una vez menos
	jr nz,canal_orden_fc_vuelve		;b8c7
	inc hl			;b8c9   ; ya: sigue
	jr canal_orden_sigue		;b8ca
canal_orden_fc_vuelve:
	ld hl,(0e2c7h)		;b8cc   ; a la marca 1
	jr canal_orden_sigue		;b8cf
canal_orden_fb:		; 0xFB n: la marca 2
	cp 0fbh		;b8d1   ; 0xFB n: el segundo bucle
	jr nz,canal_orden_fa		;b8d3
	inc hl			;b8d5   ; cuantas veces...
	ld a,(hl)			;b8d6
	ld (iy+006h),a		;b8d7   ; ...en +6
	inc hl			;b8da
	ld (0e2c9h),hl		;b8db   ; la marca 2
canal_orden_sigue:		; Sigue leyendo
	ld (0e2c3h),hl		;b8de   ; por donde va
	jr canal_byte		;b8e1
canal_orden_fa:		; 0xFA: vuelve a la marca 2
	cp 0fah		;b8e3   ; 0xFA: su final
	jr nz,canal_orden_f9		;b8e5
	dec (iy+006h)		;b8e7   ; una vez menos
	jr nz,canal_orden_fa_vuelve		;b8ea
	inc hl			;b8ec   ; ya: sigue
	jr canal_orden_sigue		;b8ed
canal_orden_fa_vuelve:
	ld hl,(0e2c9h)		;b8ef   ; a la marca 2
	jr canal_orden_sigue		;b8f2
canal_orden_f9:		; 0xF9 n: la marca 3
	cp 0f9h		;b8f4   ; 0xF9 n: el tercer bucle
	jr nz,canal_orden_f8		;b8f6
	inc hl			;b8f8   ; cuantas veces...
	ld a,(hl)			;b8f9
	ld (iy+007h),a		;b8fa   ; ...en +7
	inc hl			;b8fd
	ld (0e2cbh),hl		;b8fe   ; la marca 3
	jr canal_orden_sigue		;b901
canal_orden_f8:		; 0xF8 (o mas): vuelve a la marca 3
	dec (iy+007h)		;b903   ; una vez menos
	jr nz,canal_orden_f8_vuelve		;b906
	inc hl			;b908   ; ya: sigue
	jr canal_orden_sigue		;b909
canal_orden_f8_vuelve:
	ld hl,(0e2cbh)		;b90b   ; a la marca 3
	jr canal_orden_sigue		;b90e
canal_ruido:		; 0xF0: una nota de ruido (el periodo y su barrido) y su duracion; el canal, a ruido en el registro 7
	call ruido_pon		;b910   ; el ruido
	inc hl			;b913
	call nota_pon		;b914
	inc hl			;b917
	ld (0e2c3h),hl		;b918
	ld a,(0e088h)		;b91b
	res 3,a		;b91e
	set 0,a		;b920
	jp canal_mezcla		;b922
ruido_barrido:		; El barrido del ruido: cada tantos cuadros, el periodo + el paso, unas cuantas veces
	ld a,(0e2b6h)		;b925   ; hay ruido?
	and a			;b928
	ret z			;b929
	ld a,(0e2b7h)		;b92a   ; con barrido?
	and a			;b92d
	ret z			;b92e
	ld a,(0e2b9h)		;b92f   ; quedan pasos?
	and a			;b932
	ret z			;b933
	ld a,(0e2bbh)		;b934   ; la espera...
	dec a			;b937   ; ...un cuadro menos
	ld (0e2bbh),a		;b938
	ret nz			;b93b
	ld a,(0e2b9h)		;b93c   ; un paso menos
	dec a			;b93f
	ld (0e2b9h),a		;b940
	ld a,(0e2bah)		;b943   ; otra vez la espera
	ld (0e2bbh),a		;b946
	ld a,(0e2b8h)		;b949   ; el periodo...
	ld b,a			;b94c
	ld a,(0e2bch)		;b94d   ; ...mas el paso
	add a,b			;b950
	ld (0e2b8h),a		;b951
	jp psg_ruido		;b954   ; al registro 6
canal_un_paso:		; Un paso del canal de trabajo, que es el A (0xE2D5)
	ld (0e2d5h),a		;b957   ; el canal
	call canal_paso		;b95a
	ret			;b95d
pedido_mira:		; C si lo pedido (HL + 1) va antes (numero menor) que lo que suena (HL)
	ld b,(hl)			;b95e   ; lo que suena
	inc hl			;b95f
	ld a,(hl)			;b960   ; lo pedido
	and a			;b961   ; nada pedido: NC
	ret z			;b962
	cp b			;b963   ; menor: C
	ret			;b964
canal_cuenta:		; La cuenta de la nota: un cuadro menos; acabada, A = 1; con volumen 15 la envolvente corta, si no la que baja el volumen
	inc hl			;b965   ; la duracion...
	dec (hl)			;b966
	jp z,canal_cuenta_fin		;b967
	inc hl			;b96a   ; la envolvente
	ld a,(hl)			;b96b
	and a			;b96c
	jp z,canal_cuenta_sigue		;b96d
	cp 00fh		;b970   ; 15: la envolvente corta
	jr z,canal_cuenta_15		;b972
	inc hl			;b974
	dec (hl)			;b975   ; la cuenta de la envolvente
	jr nz,canal_cuenta_sigue		;b976
	dec hl			;b978
	ld a,(hl)			;b979   ; la espera...
	inc hl			;b97a
	ld (hl),a			;b97b   ; ...otra vez
	inc hl			;b97c
	dec (hl)			;b97d   ; el volumen, uno menos
	ld a,(hl)			;b97e
	call psg_c		;b97f   ; al PSG
	and a			;b982
	jr nz,canal_cuenta_sigue		;b983
	dec hl			;b985   ; volumen 0: sin envolvente
	dec hl			;b986
	ld (hl),a			;b987
canal_cuenta_sigue:
	xor a			;b988
	ret			;b989
canal_cuenta_15:
	inc hl			;b98a
	dec (hl)			;b98b   ; la cuenta
	jr nz,canal_cuenta_sigue		;b98c
	xor a			;b98e
	dec hl			;b98f
	ld (hl),a			;b990   ; el volumen a 0
	call psg_c		;b991
	ret			;b994
canal_cuenta_fin:
	dec hl			;b995   ; acabada
	xor a			;b996
	ld (hl),a			;b997   ; acabada: A = 1
	ld a,001h		;b998   ; 1
	ret			;b99a
ruido_pon:		; El ruido: su periodo fijo o con barrido (periodo, cuantas veces, cada cuanto, el paso)
	ld (iy+000h),a		;b99b   ; la nota
	inc hl			;b99e
	ld a,(hl)			;b99f   ; con barrido?
	ld (0e2b7h),a		;b9a0   ; con barrido (cuantas veces)?
	and a			;b9a3
	jr nz,ruido_barre		;b9a4
	inc hl			;b9a6   ; sin barrido
	ld a,(hl)			;b9a7   ; el periodo...
	ld (0e2b8h),a		;b9a8
	call psg_ruido		;b9ab   ; ...registro 6
	xor a			;b9ae   ; sin barrido
	ld (0e2b9h),a		;b9af
	ld (0e2bah),a		;b9b2
	ld (0e2bbh),a		;b9b5
	ld (0e2bch),a		;b9b8
	inc a			;b9bb   ; hay ruido
	ld (0e2b6h),a		;b9bc
	ret			;b9bf
ruido_barre:
	ld (0e2b6h),a		;b9c0   ; hay ruido con barrido
	ld (0e2bch),a		;b9c3
	inc hl			;b9c6
	ld a,(hl)			;b9c7   ; el periodo...
	ld (0e2b8h),a		;b9c8
	call psg_ruido		;b9cb   ; ...registro 6
	inc hl			;b9ce
	ld a,(hl)			;b9cf   ; cuantas veces...
	ld (0e2b9h),a		;b9d0
	inc hl			;b9d3
	ld a,(hl)			;b9d4   ; ...cada cuanto
	ld (0e2bah),a		;b9d5
	ld (0e2bbh),a		;b9d8
	ret			;b9db
nota_pon:		; Una nota: la mitad alta del byte es la duracion (la tabla 0xBA2F, o el byte siguiente con 0xE), la baja el volumen (15: la mitad)
	ld a,(hl)			;b9dc   ; la nota...
	ld (iy+000h),a		;b9dd
	and 00fh		;b9e0   ; ...el volumen (la mitad baja)
	ld (iy+002h),a		;b9e2
	ld a,(hl)			;b9e5   ; la duracion (la mitad alta)...
	and 0f0h		;b9e6
	rrca			;b9e8
	rrca			;b9e9
	rrca			;b9ea
	rrca			;b9eb
	cp 00eh		;b9ec   ; ...0xE: en el byte siguiente
	jr z,nota_duracion_byte		;b9ee
	ld de,0ba2dh		;b9f0   ; la tabla de duraciones
	add a,e			;b9f3   ; + la mitad alta
	jr nc,nota_duracion		;b9f4
	inc d			;b9f6   ; acarreo
nota_duracion:
	ld e,a			;b9f7
	ld a,(de)			;b9f8   ; la duracion
	jr nota_volumen		;b9f9
nota_duracion_byte:
	inc hl			;b9fb
	ld a,(hl)			;b9fc
nota_volumen:
	ld (iy+001h),a		;b9fd   ; la duracion
	ld a,(iy+002h)		;ba00   ; volumen 15?
	cp 00fh		;ba03
	jr nz,nota_cuenta		;ba05
	ld a,(iy+001h)		;ba07   ; la duracion...
	push bc			;ba0a   ; (guardado)
	ld c,a			;ba0b
	srl a		;ba0c   ; ...menos la mitad: la espera
	ld b,a			;ba0e
	ld a,c			;ba0f
	sub b			;ba10
	pop bc			;ba11   ; (recuperado)
nota_cuenta:
	ld (iy+003h),a		;ba12   ; la cuenta de la envolvente
	ld a,00fh		;ba15   ; el volumen 15
	ld (iy+004h),a		;ba17
	jp psg_c		;ba1a   ; al PSG
nota_tono:		; El tono de la nota: dos bytes (el alto, por debajo de 0x10, al registro B + 1) o uno (al registro B)
	inc hl			;ba1d   ; el byte siguiente
	ld a,(hl)			;ba1e
	cp 010h		;ba1f   ; por debajo de 0x10: el byte alto
	jr nc,L_BA28		;ba21
	call psg_b1		;ba23
	inc hl			;ba26   ; el bajo
	ld a,(hl)			;ba27
L_BA28:
	call psg_b		;ba28
	inc hl			;ba2b   ; el siguiente
	ret			;ba2c

; ----------------------------------------------------------------------
; DATOS duraciones: Las duraciones de las notas (la mitad alta del byte, 0-13)
;   0xba2d..0xba3b  (14 bytes)
DATA_duraciones:
	defb 080h,060h,040h,030h,020h,018h,010h,00ch,008h,006h,004h,003h,002h,001h	; ba2d  .`@0 .........

; ======================================================================
; CODIGO 0xba3b..0xbb36  (251 bytes)
; ======================================================================


psg_c:		; WRTPSG: el registro C
	ld e,a			;ba3b   ; el valor...
	ld a,c			;ba3c   ; ...el registro C
psg:
	jp 00093h		;ba3d   ; WRTPSG
psg_b:		; El registro B
	ld e,a			;ba40   ; el registro B
	ld a,b			;ba41
	jr psg		;ba42
psg_b1:		; El registro B + 1
	ld e,a			;ba44   ; el registro B + 1
	ld a,b			;ba45
	inc a			;ba46
	jr psg		;ba47
psg_mezcla:		; El registro 7
	ld e,a			;ba49   ; el registro 7
	ld a,007h		;ba4a
	jr psg		;ba4c
psg_ruido:		; El registro 6
	ld e,a			;ba4e   ; el registro 6
	ld a,006h		;ba4f
	jr psg		;ba51
musica_empieza:		; Una musica: los tres canales de la tabla 0xB700 (6 bytes por musica: la musica N en 0xB700 + 6N)
	ld hl,0b700h		;ba53   ; la tabla de musicas
	ld a,(0e2beh)		;ba56   ; la pedida...
	ld (0e2bdh),a		;ba59   ; ...suena
	ld b,a			;ba5c   ; x 6
	add a,b			;ba5d
	add a,b			;ba5e
	add a,b			;ba5f
	add a,b			;ba60
	add a,b			;ba61
	call canal_a_tabla		;ba62
	inc hl			;ba65
	call canales_bc		;ba66
	ld (0e28ah),a		;ba69   ; sin nota en marcha
	ld (0e2beh),a		;ba6c   ; el pedido, gastado
	ld a,0f8h		;ba6f   ; el mezclador: los tres canales con tono
L_BA71:
	ld (0e088h),a		;ba71
	call psg_mezcla		;ba74
	jp sonido_canal_a		;ba77
musica_acaba:		; La musica acabada: otra pedida, o el sonido a cero
	ld a,(0e2beh)		;ba7a   ; otra pedida?
	and a			;ba7d
	jr nz,musica_empieza		;ba7e
	ld (0e2bdh),a		;ba80   ; ninguna suena
	dec a			;ba83
sonido_cero:		; El mezclador A y los canales (0xE280, 0x43 bytes) a cero
	ld (0e088h),a		;ba84
	call psg_mezcla		;ba87
	ld hl,0e280h		;ba8a   ; los canales...
	ld b,043h		;ba8d   ; ...0x43 bytes...
cero_b:		; B bytes de HL a cero
	ld (hl),000h		;ba8f   ; a cero
	inc hl			;ba91
	djnz cero_b		;ba92
	ret			;ba94
efecto_a_empieza:		; Un efecto del canal A (0xE2C0): su pieza de la tabla 0xB730
	ld hl,0b730h		;ba95   ; la tabla
	ld a,(0e2c0h)		;ba98   ; el pedido...
	ld (0e2bfh),a		;ba9b   ; ...suena
	add a,a			;ba9e   ; x 2
	call canal_a_tabla		;ba9f   ; el canal A
	xor a			;baa2   ; sin nota en marcha
	ld (0e28ah),a		;baa3
	ld (0e2c0h),a		;baa6   ; el pedido, gastado
	ld a,(0e088h)		;baa9   ; el canal A con tono
	res 0,a		;baac
	ld (0e088h),a		;baae
	call psg_mezcla		;bab1
	ld hl,0e2c0h		;bab4
	jp L_B791		;bab7
sonido_a_acaba:		; El efecto del canal A acabado (0xF7): otro pedido, o el canal A callado
	ld a,(0e2c0h)		;baba   ; otro pedido?
	and a			;babd
	jr nz,efecto_a_empieza		;babe
	ld (0e2bfh),a		;bac0   ; ninguno suena
	ld hl,0e280h		;bac3   ; el canal A a cero
	ld b,012h		;bac6
	call cero_b		;bac8
	ld a,(0e088h)		;bacb
	or 009h		;bace
L_BAD0:
	ld (0e088h),a		;bad0
	jp psg_mezcla		;bad3
L_BAD6:
	ld hl,0b740h		;bad6
	ld a,(0e2c2h)		;bad9   ; el pedido...
	ld (0e2c1h),a		;badc   ; ...suena
	add a,a			;badf   ; x 4
	add a,a			;bae0
	add a,l			;bae1
	ld l,a			;bae2
	call canales_bc		;bae3
	ld (0e2c2h),a		;bae6   ; el pedido, gastado
	ld a,(0e088h)		;bae9
	and 0f9h		;baec
	jp L_BA71		;baee
sonido_bc_acaba:		; El efecto de B y C acabado: otro pedido, o B y C callados
	ld a,(0e2c2h)		;baf1   ; otro pedido?
	and a			;baf4
	jr nz,L_BAD6		;baf5
	ld (0e2c1h),a		;baf7
	ld hl,0e292h		;bafa   ; los canales B y C...
	ld b,024h		;bafd
	call cero_b		;baff
	ld a,(0e088h)		;bb02   ; B y C callados
	or 036h		;bb05
	jr L_BAD0		;bb07
canales_bc:		; Los canales B y C desde la tabla HL
	ld e,(hl)			;bb09   ; la pieza del canal B
	inc hl			;bb0a
	ld d,(hl)			;bb0b
	ld (0e292h),de		;bb0c   ; ...y su principio
	ld (0e294h),de		;bb10
	inc hl			;bb14
	ld e,(hl)			;bb15   ; la del canal C
	inc hl			;bb16
	ld d,(hl)			;bb17
	ld (0e2a4h),de		;bb18
	ld (0e2a6h),de		;bb1c
	xor a			;bb20   ; sin nota en marcha
	ld (0e29ch),a		;bb21
	ld (0e2aeh),a		;bb24
	ret			;bb27
canal_a_tabla:		; El canal A desde la tabla
	add a,l			;bb28   ; + la musica x 6
	ld l,a			;bb29
	ld e,(hl)			;bb2a   ; el canal A: su pieza...
	inc hl			;bb2b
	ld d,(hl)			;bb2c
	ld (0e280h),de		;bb2d   ; ...y su principio
	ld (0e282h),de		;bb31
	ret			;bb35

; ----------------------------------------------------------------------
; DATOS piezas: Las piezas de las musicas y los efectos (los punteros de
;   0xB700-0xB757): notas, ruidos y ordenes 0xF0-0xFF
;   0xbb36..0xc000  (1226 bytes)
DATA_piezas:
	defb 01ch,000h,000h,0f7h,0a1h,000h,06bh,063h,035h,0f7h,0d1h,000h,010h,0d1h,080h,0d1h	; bb36  ......kc5.......
	defb 020h,0d1h,090h,0d1h,030h,0d1h,0a0h,0d1h,040h,0d1h,0b0h,0d1h,050h,0d1h,0c0h,0f7h	; bb46   ...0...@...P...
	defb 0d1h,000h,080h,0d1h,002h,080h,0d1h,000h,070h,0d1h,002h,060h,0d1h,000h,060h,0d1h	; bb56  ........p..`..`.
	defb 002h,040h,0d1h,000h,040h,0d1h,002h,020h,0d1h,000h,020h,0d1h,002h,000h,0f7h,0c1h	; bb66  .@..@.. .. .....
	defb 000h,0c0h,0c1h,0b0h,0c1h,0a0h,0c1h,090h,0c1h,0b8h,0c1h,0a8h,0c1h,098h,0c1h,088h	; bb76  ................
	defb 0f7h,0d1h,003h,080h,0d1h,0a0h,0d1h,0c0h,0d1h,0e0h,0d1h,0d0h,0d1h,0b0h,0d1h,090h	; bb86  ................
	defb 0f7h,0d1h,000h,028h,0d1h,02ah,0d1h,02ch,0d1h,02eh,0d1h,030h,0d1h,032h,0f7h,0f0h	; bb96  ...(.*.,...0.2..
